"""Human-authored curriculum data for Perfect Video modules 7–9."""

M7A = [
 {"id":"pv07-01","title":"Телефонът на терен: какво записва и кога спира","minutes":38,
  "goal":"Ще избереш надежден режим за конкретен телефон и ще докажеш, че той издържа снимачната задача.",
  "hook":"Кадърът изглежда чудесно на екрана, докато телефонът не прегрее, не спре записа или файлът не се отвори в монтажната програма.",
  "principle":"Спецификацията на модела е начало на проверката, не гаранция за резултат. Различните обективи на един телефон може да имат различни ограничения за кадри в секунда, стабилизация и HDR. Log профилът и ProRes са налични само при конкретни модели и режими; не ги включвай по навик. Високият битрейт увеличава нуждата от място, захранване и по-силен монтажен компютър.\n\nИзбери режима според изхода: къде ще се публикува, кой ще коригира цвета и какво устройство ще монтира. При кратко вертикално видео със срок SDR може да даде по-добър резултат от Log, който никой няма време да преобразува и провери.",
  "detail":"Преди платена задача запиши точния модел, версия на системата и камера приложение. Заснеми тест с избраните резолюция, кадрова честота, обектив, микрофон и формат; остави телефона да работи поне колкото най-дългия дубъл. Провери температурата, мястото, батерията, фокуса, звука и отварянето на файла в монтажния софтуер. Телефонът може да превключи обектив при слаба светлина или избрана честота.",
  "workflow":["Препиши от брифа формат, ориентация, кадрова честота, цветови изход и срок.","Провери ръководството за точния модел и кои обективи поддържат режима.","Освободи място, зареди телефона, изключи известията и свържи същия микрофон.","Запиши тест с най-дългия планиран дубъл; следи фокус, експозиция, спиране и температура.","Прехвърли оригиналния файл и провери картина, звук, ориентация и синхрон.","Запази режима като пресет само след тест; запиши и резервен режим."],
  "case":"Ресторант иска шест вертикални клипа за два часа. Телефонът предлага няколко режима, но 4K с висок битрейт пълни мястото, а Log не е подготвен в монтажната програма. Екипът пробва SDR с микрофона и прехвърля файла на монтажната станция, преди да снима менюто.",
  "failure":"Включват се най-висока резолюция, Log и максимални кадри в секунда, без да се тества моделът, обективът, мястото и софтуерът.",
  "fix":"Сравни два режима в истинската сцена. Избери този, който покрива брифа, записва непрекъснато и се възпроизвежда коректно.",
  "practice":"Направи карта за собственото си устройство: модел, камера приложение, надежден режим, налични цветови профили, свободно място и лимит за дълъг дубъл. Запиши 90-секунден тест с реалния комплект, прехвърли го и го изгледай на голям екран.",
  "acceptance":"Пробата минава без прекъсване; файлът се отваря, звукът е синхронен и няма нежелано превключване на обектив. В картата има резервен режим.",
  "source":"Apple изброява поддържаните модели и условията за ProRes; сверявай точния модел: https://support.apple.com/en-gb/109041",
  "extras":[["Измери компромиса","Сними още един кратък тест с по-лек режим. Сравни продължителност, размер на файла, плавност и време за прехвърляне; не избирай по менюто само."]],
  "questions":[
   {"type":"quiz","title":"Избери работния режим","question":"Какво доказва, че режимът е подходящ за снимачния ден?","correct":"Тест със същите настройки, обектив, звук и продължителност, после проверка на прехвърления файл.","wrong":["Че това е най-високата настройка в менюто.","Че кратък клип изглежда добре на дисплея на телефона."],"feedback":"Пълен тест показва лимитите на устройството, носителя, температурата и монтажната станция."},
   {"type":"scenario","title":"Клиентът иска Log","question":"Клиентът иска Log, но приложението не го предлага при нужната честота. Как постъпваш?","correct":"Показваш ограничението, тестваш поддържан режим и потвърждаваш избора с клиента преди снимане.","wrong":["Сменяш обектива и приемаш, че ограничението ще изчезне.","Записваш стандартен профил, но го обозначаваш като Log."],"feedback":"Режимът трябва да съответства на действителния запис и уговорения процес."},
   {"type":"quiz","title":"Къде е компромисът","question":"Кое твърдение за Log и висок битрейт е надеждно?","correct":"Ползвай ги, когато тестът и монтажният процес показват полза за този проект.","wrong":["Винаги използвай Log; той автоматично създава правилен цвят.","Високият битрейт винаги прави телефона по-стабилен при дълъг запис."],"feedback":"Тези режими добавят свобода или данни, но и увеличават изискванията към устройството и постпродукцията."},
   {"type":"scenario","title":"Резервният план","question":"След 25 минути корпусът е горещ, а предстоят още интервюта. Как пазиш материала?","correct":"Спираш контролирано, проверяваш клипа, охлаждаш телефона и минаваш на предварително тестван резервен режим.","wrong":["Продължаваш до автоматичното изключване.","Изтриваш пробните клипове, докато телефонът още записва."],"feedback":"Първо защити записаното; после върни системата към доказано надежден режим."}
  ]},
 {"id":"pv07-02","title":"Мобилен комплект за платена задача: звук, опора и захранване","minutes":34,
  "goal":"Ще сглобиш лек комплект, който покрива конкретен кадър и се настройва без изненади.",
  "hook":"На място микрофонът влиза в телефона само след покупката на грешен адаптер; стойката закрива бутон, а батерията е празна преди интервюто.",
  "principle":"Комплектът започва от задачата, не от списък с аксесоари. За интервю може да са нужни телефон, микрофон, слушалки, опора, светлина и резервно захранване; за продуктови кадри може да са по-ценни статив, отражател и поставка. Проверявай връзката, физическия баланс и възможността да следиш звук, докато записваш.\n\nКейсът може да пречи на конектор, безжичният приемник заема порт, а захранването може да внася шум. Лекото решение, което работи часове, е по-полезно от тежък rig, който операторът сваля след два дубъла.",
  "detail":"Провери веригата от микрофона до файла: конектор, адаптер според устройството, захранване и мониторинг. Запиши тест с човек, който се движи; слушай със слушалки, не само по индикатора. Добави клетка само ако тя дава нужния монтаж и не закрива камерата, бутоните или порта. Носи резервен кабел и адаптер, маркирани за комплекта.",
  "workflow":["Определи нужните кадър, звук, продължителност и движение.","Напиши списък: телефон, микрофон, адаптер, слушалки, опора, светлина, батерия и кабели.","Сглоби комплекта у дома; провери достъп до бутони, камери и портове.","Запиши говор на тихо и шумно място; прослушай и двата файла.","Сними с опората и провери дали кабел или аксесоар влиза в кадъра.","Упакувай критичните адаптери и кабели отделно, с резерв за всеки."],
  "case":"Майстор обяснява ремонт в тесен сервиз. Лавалиерният микрофон е на ризата, телефонът стои на мини статив и операторът следи през слушалки. Малката лампа е отделена от телефона, за да остави място на ръцете и инструмента в кадъра.",
  "failure":"Купуват аксесоари поотделно, без да проверят дали се свързват и дали могат да работят едновременно.",
  "fix":"Сглоби пълния комплект и запиши веригата. При проблем смени един елемент и повтори теста.",
  "practice":"Сложи на масата всичко, което ще носиш на интервю. Запиши 60 секунди с говор, движение и светлина; преброй колко ръце трябват за настройка, провери кабелите в кадъра и измери времето за сглобяване.",
  "acceptance":"Комплектът се сглобява за пет минути, може да записва и следи звук едновременно, не закрива обектива и има резервен кабел или адаптер.",
  "extras":[["Полеви инвентар","Снимай сглобения комплект отгоре и запиши какво свързва всеки кабел. След снимане сверявай снимката, за да не оставиш адаптер на локацията."]],
  "questions":[
   {"type":"quiz","title":"Провери цялата верига","question":"Кое е най-доброто изпитание за микрофонния комплект?","correct":"Запис на реалното място, прослушване през слушалки и проверка на готовия файл.","wrong":["Проверка дали приемникът свети.","Гледане на нивомера без прослушване."],"feedback":"Индикаторът не показва всички проблеми с конектора, шум, прекъсване и избрания вход."},
   {"type":"scenario","title":"Несъвместим порт","question":"Телефонът няма свободен порт за захранване след включване на микрофона. Какво правиш?","correct":"Избираш съвместим маршрут за звук и захранване, после тестваш действителния запис.","wrong":["Оставяш микрофона неподключен; телефонът ще използва вградения.","Слагаш разклонител, без да провериш посоката и съвместимостта."],"feedback":"Портът е част от системата; потвърди го с реален запис, не само с механично пасване."},
   {"type":"quiz","title":"Избери какво носиш","question":"Кой аксесоар заслужава място в комплекта?","correct":"Този, който решава риска от брифа и не създава по-голям проблем с тегло, кабели или достъп.","wrong":["Най-скъпият, защото е универсален.","Всеки аксесоар, който някога може да потрябва."],"feedback":"Оразмери комплекта за задача, време и човека, който го носи."},
   {"type":"scenario","title":"Шум в записа","question":"Приемникът работи, но в слушалките има пукане при движение. Следващият ход?","correct":"Провери кабела и захвата, обезопаси връзката и повтори теста с движение преди интервюто.","wrong":["Вдигни усилването, за да заглушиш пукането.","Разчитай, че компресията ще го поправи в монтажа."],"feedback":"Първо отстрани механичната причина; обработката не поправя прекъсващ конектор."}
  ]},
 {"id":"pv07-03","title":"Движение без треперене: ръка, гимбъл или статив","minutes":36,
  "goal":"Ще избереш стабилизация по смисъла на кадъра и ще изпълниш движението без разклащане и люлеене.",
  "hook":"Гимбълът прави кадъра плавен, но камерата продължава да се движи без причина и зрителят не разбира към какво го водиш.",
  "principle":"Стабилността е избор на движение. Стативът държи гледната точка неподвижна; моноподът помага при дълъг запис и смяна на позиция; ръчният кадър може да е естествен, ако стоиш и движиш тялото контролирано. Гимбълът изглажда част от движението, но не решава лоша траектория, вертикално подскачане или претоварване.\n\nПреди включване балансирай телефона с кейса и всички аксесоари. Провери допустимата маса, ориентацията и свободното въртене. Планирай начална точка, край и скорост; ако камерата просто се плъзга през стаята, стабилизацията вече е ефект без задача.",
  "detail":"Сравни кадрите на един маршрут: ръчна опора, статив и гимбъл. Не променяй фокус и скорост по средата. Избери гледната точка, която запазва линиите вертикални, не закрива човека и оставя място за текст. На гладък под направи пробен проход; в тесен лошо осветен коридор провери завой, препятствия и спиране.",
  "workflow":["Назови какво трябва зрителят да види и защо камерата се движи.","Избери ръка, статив, монопод или гимбъл според дължината и траекторията.","Монтирай целия комплект, балансирай и калибрирай според ръководството.","Маркирай началната и крайната позиция; репетирай без запис.","Запиши два дубъла с постоянна скорост; спри движението преди важната реплика.","Изгледай на голям екран и изхвърли движението, което не добавя смисъл."],
  "case":"Кафене иска кадър от вратата до бариста. Пътят е кратък, но по него минават хора. Екипът прави един предварително репетиран проход с гимбъл и отделен статичен кадър на бариста. Движението свършва преди началото на действието, за да остане чиста точка за срез.",
  "failure":"Операторът натиска джойстика постоянно и ускорява в края; хоризонтът се накланя, а движението продължава след важния момент.",
  "fix":"Планирай начало, край и постоянна скорост. За кадър без нужда от пътешествие използвай опора и не добавяй движение.",
  "practice":"Заснеми един човек, който влиза в кадър, ръчно, на статив и с гимбъл. Сравни хоризонт, подскачане, видимост на лицето и дали движението подчертава действието. Избери дубъл и запиши какво казва движението.",
  "acceptance":"Има ясна начална и крайна точка, операторът спира камерата преди следващото действие, а хоризонтът и обектът остават контролирани.",
  "questions":[
   {"type":"quiz","title":"Дай движение причина","question":"Кога гимбълът е оправдан?","correct":"Когато предвидено движение разкрива обект или действие и операторът може да го повтори контролирано.","wrong":["При всеки кадър, защото плавността винаги е професионална.","Когато композицията не е решена и търсиш нещо интересно."],"feedback":"Гимбълът е опора за конкретна траектория, не заместител на композицията."},
   {"type":"scenario","title":"Накланящ се хоризонт","question":"Хоризонтът бавно се накланя, въпреки че телефонът е центриран. Какво проверяваш?","correct":"Баланс на пълния комплект, калибриране и режим на мотора; после правиш нов тест.","wrong":["Увеличаваш скоростта, за да не личи наклонът.","Добавяш монтажна стабилизация, без да провериш баланса."],"feedback":"Неправилен баланс натоварва моторите; провери комплекта преди да ходиш на локация."},
   {"type":"quiz","title":"Избери простата опора","question":"Кой кадър печели от статив?","correct":"Интервю или демонстрация, в която зрителят трябва да следи лице и ръце спокойно.","wrong":["Всеки кадър в движение.","Кадър, който ще бъде ускорен в монтажа."],"feedback":"Стабилният хоризонт помага при продължително гледане и точни действия."},
   {"type":"scenario","title":"Тесен коридор","question":"Гимбълът закача стената по маршрута, а кадърът трябва да покаже само табела и врата. Какво правиш?","correct":"Фиксираш телефона на опора или снимаш кратък ръчен кадър от безопасна позиция.","wrong":["Правиш по-бърз проход и се надяваш да не удариш.","Добавяш аксесоари към гимбъла за стабилност."],"feedback":"Избирай решение по задачата и пространството; не рискувай хора и техника за ненужно движение."}
  ]},
 {"id":"pv07-04","title":"Чист говор и използваема светлина с малък комплект","minutes":42,
  "goal":"Ще поставиш микрофон и светлина така, че гласът да е разбираем, лицето да е четимо, а комплектът безопасен.",
  "hook":"Интервюто е в кухня; музиката е тиха, но вентилаторът на лампата и шумът от улицата правят отговора неизползваем.",
  "principle":"Постави микрофона близо до говорещия, без триене в дреха и без да влиза в кадър. Запиши тест и го прослушай със слушалки. Насочи наличната светлина спрямо лицето; не осветявай фона по-силно от човека, освен ако това е замислено. Ограничѝ смесването на дневна светлина и лампи с различна температура.\n\nЕдна лампа не е длъжна да прави сцената равна. Премести човека, завърти стола или използвай бяла повърхност за запълване. Дифузията омекотява сянката, но поглъща светлина. Провери трептенето на конкретната лампа при избраните настройки на камерата.",
  "detail":"Не пипай шумопотискане, преди да премахнеш очевидната причина: далечен микрофон, свободен кабел, климатик или вятър. Постави приемника така, че да не закрива камерата; следи пиковете и слушай речта. За светлината провери тест с реална експозиция, отблясък в очите, детайл по лицето и цветни отражения от стените.",
  "workflow":["Изслушай стаята 20 секунди и изключи шумовете, които контролираш.","Постави микрофона близо до устата и закрепи кабела без да докосва плат или коса.","Запиши нормална и най-силна реплика; провери ги през слушалки.","Премести човека спрямо прозореца или лампата, преди да увеличиш яркостта.","Добави бяла повърхност от сенчестата страна само ако лицето губи детайл.","Провери теста на телефон и отделен екран; повтори при смяна на място."],
  "case":"Интервю с готвач в работеща кухня. Аспираторът не може да се изключи. Вместо да чисти шума после, операторът приближава лавалиерния микрофон, избира по-тих ъгъл и записва тест по време на реалната работа. Прозорецът остава ключова светлина, а малка лампа връща детайл в очите.",
  "failure":"Микрофонът остава върху телефона, а ярката лампа сочи директно към лъскаво лице.",
  "fix":"Приближи микрофона до източника, намали шума и промени позицията на светлината; оцени записан тест.",
  "practice":"Запиши едно изречение с три положения на микрофона и две положения на светлината. Изслушай шестте варианта при еднаква сила и сравни разбираемост, търкане, сенки и отблясъци.",
  "acceptance":"Гласът се разбира през телефонен говорител, няма пукане или търкане, а светлите части на лицето запазват детайл.",
  "source":"Shure обяснява позиционирането и характеристиките на микрофони: https://www.shure.com/en-US/docs/education/Microphone-Techniques-for-Recording",
  "questions":[
   {"type":"quiz","title":"Започни от причината","question":"Интервюто има силен шум от стаята. Кой е първият ход?","correct":"Приближи микрофона, намали контролируемия шум и прослушай нов тест.","wrong":["Включи максимално шумопотискане върху целия диалог.","Вдигни усилването, за да компенсираш далечния микрофон."],"feedback":"Позицията спрямо гласа често е по-важна от последващата обработка."},
   {"type":"scenario","title":"Шум от дрехата","question":"В слушалките чуваш търкане при завъртане. Как продължаваш?","correct":"Пренареждаш микрофона и кабела, повтаряш движението и прослушваш нов тест.","wrong":["Продължаваш, защото зрителят няма да забележи.","Преместваш микрофона по-далеч от говорещия."],"feedback":"Премахни механичния шум на площадката; шумодавът може да повреди речта."},
   {"type":"quiz","title":"Омекоти лицето","question":"Сянката под носа е твърда. Какво пробваш?","correct":"Променяш посоката или видимия размер на източника и проверяваш нов кадър.","wrong":["Вдигаш мощността и насочваш лампата право към лицето.","Изсветляваш всички сенки максимално в монтажа."],"feedback":"Посоката и размерът определят характера на сянката; повече мощност не омекотява светлина."},
   {"type":"scenario","title":"Смесен цвят","question":"Лицето е зеленикаво от таванните лампи, но прозорецът е чист. Какво правиш?","correct":"Изключваш или изключваш от сцената зеления източник, после балансираш бялото спрямо ключовата светлина.","wrong":["Оставяш всички лампи и избираш произволен баланс на бялото.","Коригираш оттенъка по памет след снимките."],"feedback":"Премахни цветен източник, когато той разваля кожата и не е сюжетно необходим."}
  ]},
 {"id":"pv07-05","title":"Монтаж на телефона и AI функции: ускорявай без да губиш контрол","minutes":40,
  "goal":"Ще редактираш кратък клип на телефон, ще използваш автоматични инструменти като чернова и ще провериш финалния файл.",
  "hook":"Автоматичните субтитри изглеждат почти правилни, но грешат името на лекарство и закриват логото на клиента.",
  "principle":"Мобилното приложение може да ускори подрязване, синхронизация, субтитри и версии за различен формат. То не поема отговорността за смисъл, факти, съгласие или цвят. Транскриптът е чернова: провери собствени имена, числа, отрицания, пунктуация и паузи. Не качвай чувствителен материал в облачен инструмент, преди да разбереш условията за обработка.\n\nРаздели оригинали, монтаж и експорти. Не унищожавай оригинала с автоматично изрязване или презапис. За музика, шрифт, шаблон или стоков клип провери лиценз за клиентската и платформена употреба. При предаване кажи коя част е автоматично генерирана и коя е редактирана.",
  "detail":"Малкият екран скрива кадър, който е твърде тъмен, текст върху лице или грешна последователност на думите. Изгледай експорта от начало до край; отвори субтитрите отделно и провери четливостта им спрямо речта. Ако AI инструментът изрязва паузи, сравни с оригинала: паузата може да пази смисъл или естествено дишане.",
  "workflow":["Импортирай копия и пази оригиналните медии отделно.","Сглоби ясна чернова по брифа, преди автоматични ефекти и преходи.","Генерирай транскрипт само ако е полезен; посочи езика и свери всяка реплика.","Провери кадър по кадър за изрязано лице, продукт, лого или текст.","Експортирай проба и гледай я на телефон със звук и без звук.","Запази нова версия, изходен проект и бележка за лицензи и инструменти."],
  "case":"Клиент изпраща 40 секунди съвет от физиотерапевт и иска 25-секундно вертикално видео. Автоматичният инструмент предлага изрязване и субтитри. Монтажистът пази оригинала, проверява медицинските термини, връща важно уточнение, добавя читим надпис и експортира проба за одобрение.",
  "failure":"Автоматичните субтитри се приемат за финални, оригиналът се изтрива и монтажът се експортира без преглед.",
  "fix":"Пази оригинала, сверявай автоматичния текст със звука и гледай целия експорт в целевия формат.",
  "practice":"Избери 20 секунди собствен говор. Създай транскрипт, отбележи грешките в имена, числа и паузи, коригирай ръчно и направи два варианта — със и без надписи. Провери ги на телефон.",
  "acceptance":"Текстът съвпада с речта, оригиналът е запазен, надписите не закриват важен обект, а изходът се отваря на друго устройство.",
  "source":"Adobe описва автоматичната транскрипция и редактирането на текст; провери резултата спрямо записа: https://helpx.adobe.com/premiere/desktop/add-text-images/insert-captions/auto-transcribe-video-using-speech-to-text.html",
  "questions":[
   {"type":"quiz","title":"Автоматичният текст е чернова","question":"Кога транскриптът е готов за клиент?","correct":"След сверяване дума по дума за имена, числа, отрицания и синхрон.","wrong":["Когато приложението няма червено подчертаване.","Когато е избран правилният език, дори без прослушване."],"feedback":"Сходно звучаща дума може да промени медицински, финансов или правен смисъл."},
   {"type":"scenario","title":"Поверителен запис","question":"Записът съдържа данни на клиент, а облачното приложение не обяснява къде ги пази. Какво правиш?","correct":"Не качваш материала, докато условията не са одобрени; ползваш разрешен или локален процес.","wrong":["Качваш го за кратко и изтриваш проекта след експорта.","Премахваш логото, но оставяш имена и съдържание."],"feedback":"Изтриването след качване не доказва какво е било обработено. Провери условията преди качване."},
   {"type":"quiz","title":"Пази оригинала","question":"Защо оригиналните клипове трябва да останат отделно?","correct":"Позволяват поправка, друг формат и предаване без загуба от презапис или автоматично изрязване.","wrong":["Приложенията работят само при дублирани файлове.","Оригиналът винаги има по-добър цвят от експорта."],"feedback":"Непромененият източник може да се възстанови; експортираният клип е само един изход."},
   {"type":"scenario","title":"Грешно име в надписа","question":"Субтитърът променя името на лекарство. Какво е първото действие?","correct":"Сверяваш го с аудиото и потвърденото изписване, после преглеждаш целия текст отново.","wrong":["Оставяш автокорекцията, защото думата изглежда близка.","Изрязваш репликата, без да провериш дали смисълът остава."],"feedback":"Съдържанието трябва да е вярно. При съмнение поискай потвърждение, не предполагай."}
  ]},
 {"id":"pv07-06","title":"Една снимачна смяна, няколко готови формата","minutes":35,
  "goal":"Ще заснемеш материал за няколко формата, без да губиш важен детайл и място за кадриране.",
  "hook":"Рекламният кадър е красив в хоризонтално видео, но вертикалната версия отрязва лицето и надписа върху опаковката.",
  "principle":"Планирай форматите преди запис. Ако са нужни вертикален и хоризонтален изход, направи отделни композиции или остави място за прекомпозиране. Централната зона не е универсална: интерфейс на платформа, субтитри и марка имат различни граници. Провери актуалното изискване на канала, вместо да използваш стара схема.\n\nСписъкът с кадри трябва да покрива действие, детайл, реакция и монтажни свръзки. Сними чист кадър без надпис и остави пауза до и след действието. Серийното снимане не означава една и съща поза дванадесет пъти.",
  "detail":"Смени едно нещо наведнъж: ориентация, ракурс, план или действие. Кажи на таланта кога започва дубълът, задръж кадър след движението и не закривай продукт с субтитри. За хоризонталния вариант провери дали има широк кадър, който показва мястото.",
  "workflow":["Извади от брифа форматите, продължителности, надписи и канали.","Начертай рамка за всеки формат и маркирай зона за текст и интерфейс.","Подреди shot list по сет и действие; отбележи отделните композиции.","Сними установяващ кадър, действие, детайл, реакция и чисти свръзки.","След ключов дубъл провери дали всеки формат пази лице, продукт и текст.","Избери добър дубъл и запиши кога прекомпозиране не е подходящо."],
  "case":"Производител на чай иска 16:9 за сайт и 9:16 за социална публикация. В широкия кадър чашата и ръката са далеч една от друга. Екипът прави отделен вертикален детайл на наливането; не разчита, че изрязването ще запази парата и етикета.",
  "failure":"Всички кадри се записват хоризонтално, защото монтажистът ще ги изреже после за телефон.",
  "fix":"Запиши ключовото действие отделно във всеки нужен формат; изрязвай само ако източникът има достатъчно резолюция и пространство.",
  "practice":"Заснеми просто действие в широк и вертикален формат. Направи три кадъра за всеки и провери мащаба на лицето или продукта, текстовата зона и началото/края на действието.",
  "acceptance":"И двата формата имат установяващ кадър, детайл и свръзка; нищо важно не изчезва при реалното изрязване.",
  "source":"YouTube публикува актуални препоръки за съотношение и резолюция; изискванията на целевия канал сверявай преди снимане: https://support.google.com/youtube/answer/6375112",
  "questions":[
   {"type":"quiz","title":"Планирай изходите","question":"Кога решаваш дали трябват отделни вертикални кадри?","correct":"Преди снимките, когато форматът и мястото на надписите са част от брифа.","wrong":["След като хоризонталният монтаж е заключен.","Когато автоматичното изрязване не разпознае лице."],"feedback":"Форматът влияе на композицията още на снимачната площадка."},
   {"type":"scenario","title":"Отрязана опаковка","question":"В пробата за телефон етикетът излиза от кадър. Какво правиш?","correct":"Снимаш отделен вертикален дубъл с етикета в безопасната зона и място около него.","wrong":["Оставяш го, понеже се вижда в 16:9.","Увеличаваш цифровото приближение, докато влезе."],"feedback":"Отделен ракурс често запазва детайла по-добре от силно цифрово изрязване."},
   {"type":"quiz","title":"Остави материал за монтаж","question":"За какво служат секундите преди и след действието?","correct":"Дават чисти точки за монтаж и позволяват движение да започне или завърши естествено.","wrong":["Увеличават дължината без друга цел.","Нужни са само при хоризонтален формат."],"feedback":"Handle-ите улесняват ритъма и могат да спестят повторно заснемане."},
   {"type":"scenario","title":"Искат и сайт, и сторис","question":"Клиентът добавя хоризонтален вариант след вертикалната снимка. Какво правиш?","correct":"Проверяваш наличната ширина; за липсващото действие планираш допълнителен дубъл.","wrong":["Разпъваш вертикалното изображение до широк екран.","Обрязваш лицето, за да запълниш хоризонталния кадър."],"feedback":"Не разтягай пропорции и не жертвай съдържание; договори нужната добавка."}
  ]},
 {"id":"pv07-07","title":"Провери кадрите още на локацията","minutes":31,
  "goal":"Ще одитираш суровия материал, преди екипът и картите да напуснат мястото.",
  "hook":"Снимките приключват и светлината е прибрана; в монтажната стая става ясно, че важният отговор е извън фокус.",
  "principle":"Проверявай по критериите, които могат да провалят задачата: покритие, фокус и експозиция, звук, непрекъснатост и наличност на файл. Галерията не доказва, че файлът е цял или микрофонът е записал правилния канал. Увеличи детайлите и прослушай ключовите реплики.\n\nПрави одита преди да местиш камера, таланти или реквизит. Ако има проблем, отбележи точно коя реплика или кадър липсва и направи pickup. Не форматирай карта, докато няма потвърдено копие извън телефона.",
  "detail":"Провери дали клипът съдържа началото и края на репликата, дали очите и продуктът са на фокус, дали светлите части пазят детайл и звукът няма щракване. Свери бележката с номерата на клиповете. Ако копираш на място, провери броя файлове и отвори поне един оригинал от копието.",
  "workflow":["Сравни shot list с наличните файлове и маркирай пропуските.","Изгледай начало, среда и край на ключовите клипове с увеличен екран.","Прослушай всяка важна реплика; провери канал, пикове и фонов шум.","Провери фокус, експозиция и дали кадърът не е закрит от ръка или аксесоар.","Повтори липсващия кадър и отбележи добрия дубъл в листа.","Направи копие и отвори файл от него преди форматиране на носителя."],
  "case":"В интервюто има добър отговор, но дубълът започва след първата дума. Операторът проверява картата на място, намира че микрофонът е записал отделен канал и прави pickup на цялата реплика с пауза преди и след нея.",
  "failure":"Клипът се гледа като миниатюра, а звукът се приема за добър, защото нивомерът не е червен.",
  "fix":"Проверявай с увеличен образ и слушалки. За критичен кадър потвърди съдържанието, цял дубъл и четим звук.",
  "practice":"Направи одитен лист с покритие, фокус/експозиция, звук, непрекъснатост и копие. Провери три реални клипа и отбележи резултатите; ако кадър липсва, заснеми го отново.",
  "acceptance":"Показваш къде е всеки кадър от брифа, кой дубъл е избран и че файл се отваря от отделно копие.",
  "questions":[
   {"type":"quiz","title":"Първо място за одит","question":"Кога проверяваш важните клипове?","correct":"Докато човекът, реквизитът и локацията са готови за повторение.","wrong":["След като картата е форматирана.","Когато монтажистът поиска нов дубъл."],"feedback":"Ранното откриване спестява повторна логистика и липсващ материал."},
   {"type":"scenario","title":"Неясен глас","question":"Миниатюрата изглежда добре, но не си чул звука. Какво правиш преди да освободиш госта?","correct":"Слушаш ключовите реплики през слушалки и при проблем повтаряш дубъла или записваш нужния тон.","wrong":["Приемаш, че телефонът е записал, защото микрофонът светеше.","Добавяш компресия в монтажната програма."],"feedback":"Индикацията не замества прослушването; отстрани дефекта на локацията, ако можеш."},
   {"type":"quiz","title":"Провери копието","question":"Кое доказва, че файлът е прехвърлен?","correct":"Отваряш оригинал от новото място и проверяваш целия му ход.","wrong":["Виждаш папка със същото име.","Копираш само папка с миниатюри."],"feedback":"Папката и иконата не доказват, че медиата е цяла."},
   {"type":"scenario","title":"Фокусът е избягал","question":"На ключовата реплика лицето е размазано. Кое решение е правилно?","correct":"Проверяваш за друг остър дубъл; ако няма, повтаряш репликата с проверен фокус.","wrong":["Оставяш го, защото малък екран скрива размазването.","Прилагаш sharpening до максимум върху клипа."],"feedback":"Оцени наличния материал честно и поправи заснемането, ако е възможно."}
  ]},
 {"id":"pv07-08","title":"60 минути от бриф до проверен файл","minutes":45,
  "goal":"Ще превърнеш ограничен бриф в един кратък клип, като разпределиш време и не прескочиш контрола.",
  "hook":"Шейсет минути стигат за прост клип, но не и за неуточнен сценарий, пет локации и неограничени редакции.",
  "principle":"Спринтът е рамка за ограничен обхват, не обещание за всяко видео. Използвай една теза, един говорещ, една локация, одобрен текст и ясна дължина. Добави време за тест и предаване. Ако брифът изисква графика, права или множество монтажи, преоцени срока преди старта.\n\nРазпредели времето за подготовка, снимане, импорт, чернова, преглед и експорт. Записвай търсене на файлове и грешни дубъли. Не харчи целия буфер за украса; остави време за финален преглед и възпроизвеждане на експорта.",
  "detail":"Преди таймера заключи формат, име на файл, лого, музикален лиценз, начин за одобрение и кой може да поиска поправка. Направи shot list от малко кадри. Таймерът свършва, когато клиентът получи линк или файл, не когато натиснеш Export.",
  "workflow":["0–8 минути: преформулирай целта, аудиторията, едно действие и задължителното твърдение.","8–18: подреди 4–6 кадъра; провери телефон, звук, светлина и място.","18–30: заснеми основното действие и резервен дубъл за трудните кадри.","30–42: импортирай и сглоби ясна последователност без украса.","42–52: провери субтитри, лого и музика, само ако са нужни.","52–60: експортирай, изгледай целия файл, провери името и изпрати статуса."],
  "case":"Пекарна иска 20-секунден клип за нов сладкиш: едно изречение от собственика, кадър на продукта и покана за поръчка. Няма актьор, външна локация или графика. Един час е реалистичен, ако има готови права, текст и одобрител.",
  "failure":"Времето отива за шрифт и преходи; файлът се изпраща без гледане и се казва final_final2.mp4.",
  "fix":"Заключи обхват и защити буфер за QA. Провери файла като получател: отваря ли се, правилно ли е ориентиран и има ли звук.",
  "practice":"Направи спринт за 15–25-секундно видео. Пусни таймер, запиши минутите за фазите и едно неочаквано забавяне. След експорта отбележи какво би махнал от обхвата при следващ поръчков срок.",
  "acceptance":"Получателят отваря правилния файл и вижда едно ясно послание. Проверени са титри, ориентация и звук; фазовото време е записано.",
  "extras":[["Кога преоценяваш","Без одобрен текст, права, локация или отговорен одобрител спринтът започва след изчистване на блокиращото условие."]],
  "questions":[
   {"type":"quiz","title":"Договори реалния обхват","question":"Кога едночасовият срок е приемлив?","correct":"Когато съдържанието, локацията, правата и одобрението са ясни, а обхватът е ограничен.","wrong":["При всяко видео под 60 секунди.","Когато монтажистът прескочи проверката."],"feedback":"Кратката дължина не значи проста продукция; обхватът прави срока възможен."},
   {"type":"scenario","title":"Брифът се разширява","question":"Клиентът добавя две локации и втори език след старта. Как реагираш?","correct":"Преоценяваш срока, показваш влиянието и договаряш нов обхват или дата.","wrong":["Пропускаш проверка на субтитрите.","Продължаваш мълчаливо и изпращаш непълен файл."],"feedback":"Професионалистът прави промяната видима и пази качеството и доверието."},
   {"type":"quiz","title":"Последно след експорта","question":"Коя дейност задължително остава след експорта?","correct":"Пълно възпроизвеждане и проверка на име, формат, звук и линк.","wrong":["Незабавна смяна към следващия клиент.","Изтриване на изходния монтаж."],"feedback":"Експортът може да прекъсне или да приложи грешни настройки; отвори готовия файл."},
   {"type":"scenario","title":"Тесен срок","question":"Остават пет минути, а музиката няма потвърден лиценз. Какво правиш?","correct":"Махаш я, проверяваш диалога и изпращаш чист вариант или съгласуваш промяната.","wrong":["Ползваш популярна песен за еднократна публикация.","Оставяш музиката тиха, без да кажеш на клиента."],"feedback":"Правата са част от доставката. Предпочети чисто предаване пред неизвестен риск."}
  ]}
]

M8B = [
 {"id":"pv08-09","title":"Папки, които водят монтажиста от брифа до export","minutes":32,
  "goal":"Ще изградиш структура на проект, в която колега намира източници, проект, версии и готов файл без въпроси.",
  "hook":"Суровият материал, експорти, проксита и договор са в една папка; при предаване липсват медии и неясно е кой файл е master.",
  "principle":"Структурата следва работния поток, не вкуса на автора. Раздели бриф/администрация, оригинална медия, звук, графики, проектни файлове, проксита, exports, handoff и архив. Пази оригиналите отделно от производните файлове и не поставяй ключови документи само на работния плот.\n\nИзползвай една и съща схема за всички проекти, но не добавяй папки, които никой не ползва. Номерирай етапите, ако редът има значение. Определи къде ще се намират файловете на всеки работен компютър и как се relink-ват; папка с красиво име не помага, ако пътищата се променят без manifest.",
  "detail":"Примерна основа: 00_Brief, 01_Admin_Rights, 02_Media/Video, 02_Media/Audio, 03_Graphics, 04_Project, 05_Proxies, 06_Exports, 07_Delivery, 08_Archive. Съгласувай с монтажния софтуер и екипната система. Носи readme с версия, aspect ratio, frame rate, цветово управление и контакт за въпроси.",
  "workflow":["Събери изисквания от монтажиста и отговорника за архива.","Създай чиста структура и readme в тестов проект.","Копирай медията в отделна папка, запази оригиналните имена и manifest.","Постави проект, проксита и exports в отделните зони.","Отвори проекта от пътя, който получателят ще използва; провери relink.","Предай структурата и кратка карта на съдържанието; забрани празни копия като стандарт."],
  "case":"Външен монтажист получава проект от агенция. Readme посочва кадри в секунда, ориентация и името на одобрената версия; папките отделят оригинали, аудио, проксита и exports. Монтажистът отваря проекта без търсене на медия.",
  "failure":"Папките се именуват с вътрешни шеги и всички версии се слагат на едно място.",
  "fix":"Въведи структура, която показва предназначение, оригинал/производно и ред на работа; пробвай я с нов колега.",
  "practice":"Направи празна структура за интервю, реклама и серия. Попълни readme и помоли човек, който не е създал папките, да намери одобрения export и суровите клипове.",
  "acceptance":"Друг колега намира бриф, медия, проект, proxy и одобрен export само по readme и имената на папките.",
  "questions":[
   {"type":"quiz","title":"Отдели източника","question":"Къде се пазят оригиналните клипове?","correct":"В отделна, ясно назована зона, отделена от проксита и exports.","wrong":["В папката на всеки монтажен вариант.","До final.mp4 без указание за източник."],"feedback":"Ясното разделяне намалява презапис и улеснява relink."},
   {"type":"scenario","title":"Монтажистът не намира медия","question":"Проектът отваря с missing files при получателя. Какъв е първият ход?","correct":"Сравняваш пътя и manifest, после relink-ваш към оригиналната медия от проверена структура.","wrong":["Заменяш всички клипове с експортиран preview.","Преименуваш случайно папките, докато се свържат."],"feedback":"Възстанови връзката по информацията за източника; не заменяй оригинали с preview."},
   {"type":"quiz","title":"Използваем readme","question":"Кое поле помага на външен редактор?","correct":"Къде са оригиналите, коя версия е одобрена и какви са техническите настройки.","wrong":["Името на човека, който е измислил папките.","Общото „всичко е вътре“."],"feedback":"Readme-то трябва да намалява реално търсене и неяснота."},
   {"type":"scenario","title":"Излишни папки","question":"Структурата има 30 празни подпапки и екипът ги игнорира. Какво правиш?","correct":"Премахваш неизползваните категории и оставяш тези, които следват действителните handoff-и.","wrong":["Добавяш още имена на категории.","Запазваш всичко, защото е по-детайлно."],"feedback":"Схемата трябва да се използва, иначе хората създават паралелни системи."}
  ]},
 {"id":"pv08-10","title":"Три копия, два носителя, едно извън мястото","minutes":40,
  "goal":"Ще приложиш правило за резервиране, провериш копието и покажеш, че материалът може да бъде възстановен.",
  "hook":"Един SSD е паднал на пода; файлът и единственото копие от вчерашното интервю са изчезнали заедно.",
  "principle":"3-2-1 обобщава разделяне на риска: три копия общо, два типа носител и едно отделно физическо място. За защита от ransomware или грешно изтриване се нуждаеш и от offline/immutable копие и история, която не се синхронизира със същата грешка. RAID или синхронизация сами по себе си не са резервно копие.\n\nКопието има смисъл, ако го провериш и можеш да го възстановиш. Задай срок, собственик и достъп. За клиентска медия уточни кога трябва да бъде изтрита; не задържай излишни лични кадри без основание.",
  "detail":"Планирай трите copies с реалните места: working SSD, втори отделен диск/NAS и off-site копие. Определи кои данни се включват, колко често се обновяват, какво е versioned, кой проверява лог и кога се прави restore drill. За интернет копие сметни скорост и срок за upload/download; не обещавай възстановяване за минути, ако терабайти прехвърлят цяла нощ.",
  "workflow":["Нарисувай къде са production, backup copies и off-site местоположението.","Провери дали двата носителя са независими и достъпите им са отделени.","Настрой периодичност, version history, encryption и отговорник.","След копиране провери лог или checksum и отвори избран файл.","Проведи restore drill в празна тестова папка и измери времето.","Запиши срок за съхранение и ред за сигурно изтриване."],
  "case":"Студио пази проект на работен SSD и синхронизира папка в облак. Екипът добавя офлайн диск в друга локация и версия на облачните файлове. Веднъж месечно възстановява случаен клип в тестова папка.",
  "failure":"Работната папка е огледална към друг диск, така че случайно изтриване се копира и върху единственото копие.",
  "fix":"Добави отделено/versioned копие и проверявай, че възстановяването работи извън production пътя.",
  "practice":"Нарисувай поток за един проект, назначи owner и направи тест restore на видео, проектен файл и един административен документ.",
  "acceptance":"Има три копия според риска на проекта, копията са отделени, restore е измерен, а срокът/отговорникът са документирани.",
  "source":"CISA насърчава offline backups, ограничения на достъпа и регулярна проверка на възстановяването: https://www.cisa.gov/stopransomware/ransomware-guide",
  "questions":[
   {"type":"quiz","title":"Разлика между sync и backup","question":"Защо синхронизацията не е достатъчно копие?","correct":"Тя може да разнесе изтриване, повреда или криптиране към синхронизираните места.","wrong":["Тя прехвърля само видео.","Тя не може да работи с облачна услуга."],"feedback":"Backup копието трябва да запазва възстановимо състояние, а не само текущото."},
   {"type":"scenario","title":"Грешно изтрита папка","question":"Папката е изтрита и sync-ът я премахна навсякъде. Какво следва?","correct":"Използваш независима версия/offline копие и възстановяваш в тестово място преди замяна.","wrong":["Правиш ново копие на празната папка.","Пускаш sync отново, за да възстанови данните."],"feedback":"Намали риск от презапис на последното копие и възстановявай първо в отделна зона."},
   {"type":"quiz","title":"Резервът трябва да се възстановява","question":"Какво прави restore drill?","correct":"Доказва, че човекът може да намери и възстанови файл от копието в измерено време.","wrong":["Потвърждава, че дискът свети.","Показва, че файловете имат познато име."],"feedback":"Съществуването на копие не доказва, че е четимо или достъпно."},
   {"type":"scenario","title":"Копие извън офиса","question":"Ограничена мрежа ще качва файловете цяла нощ. Какво планираш?","correct":"График за upload, проверка на резултат и реалистично обещание кога off-site копието е готово.","wrong":["Обявяваш го за архив веднага след старта на качването.","Компресираш оригиналите и изтриваш изхода."],"feedback":"Времето за пренос е част от плана за възстановяване."}
  ]},
 {"id":"pv08-11","title":"SSD, NAS или облак: избери според натоварването","minutes":38,
  "goal":"Ще избереш място за монтаж, обмен и архив по реална скорост, капацитет, достъп и възстановяване.",
  "hook":"Купен е бърз диск според етикета, но голям проект се прехвърля бавно, защото кабелът и компютърът са по-тесният участък.",
  "principle":"SSD е удобен за мобилен монтаж и бърз ingest; NAS позволява споделен достъп и капацитет, но скоростта зависи от мрежата, броя дискове и натоварването; облакът помага за отдалечен обмен и външно копие, но изисква пропускателна способност, права и сметка за трафик. Нито една среда не е по-бърза или по-безопасна сама по себе си.\n\nИзмери действителния трансфер с медията и проекта, не само теоретичната скорост на интерфейс. Помисли за едновременно четене/писане, шум, нагряване, път, достъп, обновяване и възстановяване. Вземи предвид дали монтажният софтуер поддържа споделена работа така, както екипът планира.",
  "detail":"Тествай прехвърляне на реална папка и измери устойчивия темп за няколко минути, след което отвори проект и scrub-ни таймлайна. За NAS измери от всяка станция; за облак провери права за споделяне, версии, изтегляне и граници на достъп. Кабел, порт, мрежов switch и диск са един общ път.",
  "workflow":["Определи дали системата ще служи за активен монтаж, екипна медия, обмен или архив.","Провери codec, размери и колко души ще четат/пишат едновременно.","Тествай истински файлове през окончателния кабел/порт/мрежа.","Симулирай прекъсване, липса на интернет и пълен диск.","Провери права, version history, отделено backup копие и restore.","Избери система и документирай какво се случва при отказ."],
  "case":"Двама редактори работят по една серия. NAS е общото място за оригиналите, локален SSD носи активния монтаж и облакът дава клиентски review. Екипът предварително тества media path, заключване на проект и скорост от двете станции.",
  "failure":"Екипът избира по рекламно число на диска и не проверява кабела, мрежата, работния софтуер или едновременния достъп.",
  "fix":"Сравни измервания с реални файлове и различни роли; пази backup отделно от media working volume.",
  "practice":"Измери едно и също копиране на локален SSD, мрежово място и облак. Запиши време, стабилност, отваряне на проекта, права и път за възстановяване.",
  "acceptance":"Решението посочва роля, реална измерена скорост, брой едновременни потребители, достъп и резерв при прекъсване.",
  "questions":[
   {"type":"quiz","title":"Измери реалната система","question":"Кое показва дали дискът стига за монтаж?","correct":"Тест с истинските файлове, окончателния порт и проекта на работната станция.","wrong":["Само стойността върху кутията.","Кратко копиране на един малък файл."],"feedback":"Най-слабата връзка в кабел/порт/мрежа/носител ограничава потока."},
   {"type":"scenario","title":"Екипът чака preview","question":"NAS е бавен само когато двама редактори монтират. Какво проверяваш?","correct":"Едновременната мрежа, дисковата натовареност и реалния workflow от всяка станция.","wrong":["Купуваш по-голям капацитет, без измерване.","Прехвърляш целия архив в облак веднага."],"feedback":"Капацитетът и скоростта са различни; измери тесния участък при паралелна работа."},
   {"type":"quiz","title":"Облакът като част от системата","question":"Какво трябва да влезе в сметката за cloud transfer?","correct":"Upload/download време, права, версии, наличност и възстановяване.","wrong":["Само месечната цена на абонамента.","Само дали клиентът може да отвори линк."],"feedback":"Пътят до медията и достъпът трябва да са предвидими."},
   {"type":"scenario","title":"Няма интернет на локацията","question":"Екипът трябва да предаде копие от място без връзка. Какво подготвяш?","correct":"Проверени локални копия на отделни носители и синхронизация към облак по-късно.","wrong":["Единствена папка в облака, която не е изтеглена.","Свързваш телефон hotspot по време на целия трансфер без тест."],"feedback":"Подготви офлайн маршрут и не превръщай връзката в единична точка на отказ."}
  ]},
 {"id":"pv08-12","title":"Архив, който може да се възстанови: срок, носител и тест","minutes":36,
  "goal":"Ще затвориш проект след доставка така, че бъдещ колега да може да намери, отвори и възстанови нужните файлове.",
  "hook":"Клиентът иска поправка след осем месеца; дискът пази видео, но липсват шрифтове, проектни връзки и версия на графиките.",
  "principle":"Архивът не е купчина стари exports. Той съдържа точно договореното: финален файл, проект, нужни медии или proxy, readme, лиценз/права и версия. Не всяка поръчка изисква да пазиш всеки дубъл завинаги. Съгласувай срока, кой има достъп, формата и начина за изтриване.\n\nИзбери носител и местоположение с оглед на срок, поддръжка и възможност да се прочете отново. Пази критичните файлове в отворени или широко поддържани формати, когато договорът го позволява. Периодично възстановявай sample проект, защото стар софтуер, липсващ шрифт или повреда прави архивната папка неполезна.",
  "detail":"Архивният manifest изброява версия на проекта, plugin/font dependencies, настройки на таймлайн и export, контролна сума, местоположение, дата на проверка и срок за изтриване. Тествай един sample clip и един project file от студен архив. Ако проектът е зависим от платен plugin, включи бележка и предвиди неутрален финален export.",
  "workflow":["Свери договора: какво се пази, срок, права и задължение за изтриване.","Събери финален файл, проект, нужни media и dependencies в архивния пакет.","Направи manifest с версия, технически настройки, пътища, checksums и дата.","Провери целостта на пакета и копията, после премахни ненужни render/cache.","Проведи restore test на отделно устройство или чиста тестова папка.","Назначи календарна проверка и сигурно изтриване в края на срока."],
  "case":"Фрилансър архивира рекламен клип с проект, използвани оригинали, шрифт с лиценз и readme. След шест месеца друг монтажист отваря проекта на чиста машина, relink-ва клиповете и вижда кой export е приет.",
  "failure":"В архива остава само MP4 или, обратно, целият scratch/cache без readme и без срок.",
  "fix":"Пази минималния възстановим пакет, тествай го и изтрий ненужното по договорения срок.",
  "practice":"Архивирай малък монтажен проект. Дай копието на колега без допълнителни инструкции и наблюдавай дали може да намери зависимостите и да възпроизведе финала.",
  "acceptance":"Пакетът има readme, одобрен export, нужни зависимости, проверени копия и срок/отговорник; тестът се повтаря на чисто място.",
  "questions":[
   {"type":"quiz","title":"Архивирай за бъдеща работа","question":"Кое прави архива повторно използваем?","correct":"Проектът, необходимите медии/зависимости, readme, одобрен export и проверка за възстановяване.","wrong":["Само export с име final.","Всички временни cache файлове без обяснение."],"feedback":"Архивът трябва да помогне за проверка и ремонт, а не само да заема място."},
   {"type":"scenario","title":"Липсващ шрифт","question":"След месеци проектът няма шрифта от титъра. Какво трябваше да съдържа пакетът?","correct":"Лицензирания dependency или уточнение за него, плюс финален export и алтернатива според правата.","wrong":["Само screenshot на титъра.","Копие от всички cache папки."],"feedback":"Записвай зависимостите и лиценза, не само пикселите в timeline."},
   {"type":"quiz","title":"Определи срок","question":"Кой определя дали да се пазят всички сурови дубли?","correct":"Договорът, правата, нуждата от повторни версии и срокът за задържане.","wrong":["Свободното място на редактора.","Автоматичната настройка на камерата."],"feedback":"Съхранението е работно и договорно решение; не пази чувствителен материал без срок."},
   {"type":"scenario","title":"Архивът не се отваря","question":"Restore test показва, че носителят е четим, но проектът липсва медия. Какво правиш?","correct":"Поправяш manifest и пакетираш необходимите източници, след което повтаряш тест на чисто място.","wrong":["Маркираш архива като успешен, защото MP4 се отваря.","Изтриваш проекта и пазиш само cache."],"feedback":"Провери конкретно обещания пакет, не само наличието на един export."}
  ]},
 {"id":"pv08-13","title":"Старите проекти в хаоса: инвентаризирай, после мести","minutes":39,
  "goal":"Ще подредиш съществуващ архив, без да изтриеш оригинал или да счупиш отворен проект.",
  "hook":"Дискът е почти пълен; в папката Final има три едноименни проекта, а някой предлага да изтрие дубликатите на око.",
  "principle":"Първо правиш инвентар, после преместване. Спри проекти, които са отворени, и отдели от тях оригиналите. Запиши размер, дата, име, клиент и къде се използва; еднакво име не доказва еднакви съдържание и версия. За дубликати сравнявай checksum или използвай инструмент с ясно представяне на конфликт.\n\nПреди да триеш или сливаш, направи backup на архива и тествай restore. Класифицирай папки като активен проект, приключен, unknown, дублиран или ограничен от права. Подозрителни или несъответстващи файлове отиват в карантина с ограничен достъп, не в кошчето.",
  "detail":"Премествай по проект, а не целия диск наведнъж. Обнови project path/manifest, relink-ни копие и помоли собственик да потвърди. Остави log с предишно и ново място. Не отваряй непознати изпълними файлове от архив и не качвай клиентски данни в публичен анализатор.",
  "workflow":["Създай read-only snapshot или резервно копие преди реорганизация.","Изведи inventory по име, размер, дата, проект и отговорник.","Отбележи активни, приключени, неизвестни, чувствителни и съвпадащи файлове.","Провери потенциални дубликати чрез checksum/съдържание, не само по име.","Премести малък batch в целевата структура и провери project relink.","Запиши промяната, собственика и повторния restore test преди освобождаване на място."],
  "case":"Предаване на външен монтажист открива две папки с почти еднакво име. Инвентарът показва, че едната съдържа последен кадър от клиентско одобрение. Екипът я преименува с версия, update-ва проекта и пази checksum отчета.",
  "failure":"Групово преименуване и изтриване се правят само по дата/име, без snapshot и проверка на връзките.",
  "fix":"Класифицирай и валидирай малки партиди; пази предишния път и backup до потвърждение.",
  "practice":"Вземи учебна папка с дублирани и липсващи файлове. Направи inventory, посочи кои са сигурни дубликати и премести само един проект, после отвори проекта от новото място.",
  "acceptance":"Има инвентар, запазен стар път, одобрен нов път и няма изтрит файл без потвърждение и работещ restore.",
  "questions":[
   {"type":"quiz","title":"Преди да местиш","question":"Кое е първото действие при хаотичен архив?","correct":"Направи проверимо snapshot/backup и инвентаризирай съдържанието.","wrong":["Преименувай всички папки по дата.","Изтрий файлове с еднакво име."],"feedback":"Необратимо действие идва след инвентар и възстановимо копие."},
   {"type":"scenario","title":"Еднакви имена","question":"Два файла имат едно име, но различен размер. Какво правиш?","correct":"Сравняваш content/checksum и произход, после запазваш правилната версия с отчет.","wrong":["Оставяш по-новия по дата и изтриваш другия.","Качваш и двата в публичен cloud detector."],"feedback":"Име и дата не доказват съдържание; пази клиентските файлове в разрешена среда."},
   {"type":"quiz","title":"Провери проекта след преместване","question":"Какво доказва, че project path е запазен?","correct":"Отваряш копие от новото място и сверяваш медията, таймлайн и export.","wrong":["Папката се появи в новата директория.","Името на файла се промени успешно."],"feedback":"Преместването е готово само когато проектът и източниците се намират."},
   {"type":"scenario","title":"Неизвестен собственик","question":"Намерена е папка с клиентски кадри и няма отговорник. Какво правиш?","correct":"Маркираш я като unknown, ограничаваш достъпа и търсиш собственик преди местене или изтриване.","wrong":["Преместваш я към общия архив без лог.","Изтриваш я, защото никой не я е поискал."],"feedback":"Неопределеният собственик означава пауза и проследяване, не свободно разпореждане."}
  ]},
 {"id":"pv08-14","title":"Екипен достъп: сподели медията, не заключи проекта","minutes":42,
  "goal":"Ще организираш споделен проект така, че хората да знаят кой редактира, как се стига до media и кой одобрява.",
  "hook":"Двама редактори презаписват един проект; друг колега отваря облачно копие, чиито пътища не работят на неговия компютър.",
  "principle":"Екипната работа изисква правила за собственост, версия и пътища. Дай достъп само на хората, които го ползват; отдели клиентски review линк от вътрешната папка с оригиналите. Не редактирай един shared project файл едновременно, освен ако софтуерът има поддържан multi-user/lock workflow и екипът го е тествал.\n\nОпредели кое е единственият master, кой го заключва, как се предават промени и къде са медийните активи. Права се отнемат при край на договора. Не изпращай public link към сурови клиентски кадри като удобен handoff.",
  "detail":"Adobe Productions организира работата с няколко проекта и общи активи; други системи имат различни ограничения. Провери текущото поведение в избрания софтуер: locking, конфликт, офлайн достъп, версии и relink. Направи проба с два тестови акаунта; не приемай, че облачният sync разрешава конфликт автоматично.",
  "workflow":["Назначи собственик на master проекта, редактор за всяка част и одобрител.","Избери споделено място за media и тестирай пътя на всяка станция.","Дай минимален достъп; направи отделен линк с read-only review за клиента.","Установи lock/checkout/версиониране според програмата.","Синхронизирай файл, отвори го на втори акаунт и реши test conflict.","При handoff отнеми излишни права и запиши кой носи следващата задача."],
  "case":"Видео поръчка се дели между монтажист и колорист. Монтажистът предава picture lock с версия и manifest; колористът връща отделен проект и exports, без да записва върху master. Клиентът вижда само review линка с ограничен срок.",
  "failure":"Всеки има редакторски достъп до едно и също project file, а review линкът отваря цялата папка.",
  "fix":"Определи master owner, работен handoff и отдели достъп за клиентски преглед от вътрешните оригинали.",
  "practice":"Създай тестов проект с два акаунта или две локални копия. Симулирай паралелна промяна, офлайн редакция и конфликт; напиши как се връща към master.",
  "acceptance":"Екипът знае кой редактира master, къде са медията, кой има review достъп и как се решава конфликт.",
  "source":"Adobe обяснява предназначението на Productions за управление на много проекти и споделени активи: https://helpx.adobe.com/premiere/desktop/collaborate-with-others/collaborate-using-productions/about-productions.html",
  "questions":[
   {"type":"quiz","title":"Един master","question":"Как се избягва конфликт при споделен проектен файл?","correct":"Определяш собственик и lock/checkout правило или използваш тествана multi-user функция.","wrong":["Всички записват едновременно; sync ще избере правилния.","Наричаш всеки проект final-copy."],"feedback":"Облачната папка сама по себе си не решава конфликт между редактори."},
   {"type":"scenario","title":"Клиентът вижда originals","question":"Review линкът отваря цялата папка с оригинали. Как реагираш?","correct":"Спираш споделянето и създаваш отделен ограничен review линк към конкретния export.","wrong":["Оставяш го, ако линкът е труден за отгатване.","Изпращаш паролата в същото съобщение."],"feedback":"Сподели само нужния файл и отнеми излишния достъп."},
   {"type":"quiz","title":"Пътят към медията","question":"Какво трябва да тестваш преди екипната работа?","correct":"Проектът се отваря от всяка станция, media path е работещ и има правило за конфликт/версии.","wrong":["Само дали всички са поканени в услугата.","Само размерът на общото хранилище."],"feedback":"Достъпът и наличното място не доказват, че редакторът може да намери медията."},
   {"type":"scenario","title":"Редактор напуска проекта","question":"Външен монтажист приключва работа. Кой екипен ход е нужен?","correct":"Отнемаш излишния достъп и прехвърляш собствеността/следващото действие по записан handoff.","wrong":["Оставяш акаунта за всеки случай.","Изтриваш проекта, за да затвориш задачата."],"feedback":"Затварянето включва достъп, отговорност и запазване на нужния материал."}
  ]},
 {"id":"pv08-15","title":"Проведи batch ден: изпълни, отбелязвай, коригирай","minutes":45,
  "goal":"Ще водиш снимачната партида по график и ще засечеш рано отклоненията, вместо да ги откриеш след деня.",
  "hook":"Първите клипове са заснети, но никой не записва дублите и едва след час екипът разбира, че микрофонът не е включен.",
  "principle":"Batch денят е оперативен процес: go/no-go check, ясно табло, собственик за всеки сет, статус на дубълите и контрол при смяна. Проверявай първия кадър на всяка нова конфигурация, преди да снимаш цяла серия. Между блоковете свери списъка, не разчитай на памет.\n\nАко екипът изостава, спри и обнови обхвата. Не режи почивка, тест или копие без съгласуване. Запиши отклонение и причината; следващият batch план трябва да използва реалните данни, не желаното темпо.",
  "detail":"Go/no-go включва човек и права готови, карта/място, батареи, звук, светлина, бриф и безопасна локация. Един човек следи slate/shot log. На всяка смяна прегледай дубъл, статус, имя файла, оригинален текст и напредък. Назначи комуникационен канал при забавяне.",
  "workflow":["Направи кратък go/no-go чеклист и провери всеки сет преди първи дубъл.","Назначи оператор, звук, лог и отговорник за одобрение.","Започни с тест, прослушай и огледай файла; заключи правилната конфигурация.","След всеки блок обнови shot log, дубъл, проблем и оставащо време.","При отклонение преоцени критичните доставки и съгласувай промяна.","В края провери материал, копия, статуса и действителния капацитет."],
  "case":"Екип снима 10 демонстрационни видеа за кухня. Shot log показва, че клип 4 има един добър дубъл, а клип 5 чака повторение. При смяна към втората камера тестът открива неправилен кадър в секунда, преди серията да е заснета.",
  "failure":"Таблото показва само „снимано“, без дубъл, QC или отворена задача.",
  "fix":"Раздели статуси: планирано, тест, заснето, проверено, pickup, копирано; записвай собственик и следващ ход.",
  "practice":"Проведи симулация на batch ден с шест клипа. Вмъкни един отказ на микрофон и едно закъснение; обнови графика и shot log.",
  "acceptance":"Проблемът е открит преди да засегне серията; приетите клипове, pickup-и и копията са видими за целия екип.",
  "questions":[
   {"type":"quiz","title":"Първо test кадър","question":"Кога тестваш нов сет или камера режим?","correct":"Преди да заснемеш цялата партида в тази конфигурация.","wrong":["След като приключи последният клип.","Само ако клиентът поиска да чуе звук."],"feedback":"Първият тест може да хване грешка, преди тя да се размножи в серията."},
   {"type":"scenario","title":"Микрофонът е изключен","question":"Shot log показва, че първите два клипа са без външен микрофон. Какво правиш?","correct":"Спираш серията, проверяваш дали има резервен звук и повтаряш клиповете, докато сетът е готов.","wrong":["Продължаваш и ще надпишеш всичко после.","Изтриваш първите клипове, за да не се виждат."],"feedback":"Провери покритието и информирай екипа; не прикривай дефект."},
   {"type":"quiz","title":"Статус, който помага","question":"Кое е най-полезно в shot log?","correct":"Дубъл, техническа проверка, проблем, оставащо действие и отговорник.","wrong":["Само отметка „снимано“.","Само тема от сценария."],"feedback":"Статусът трябва да казва какво следва и кой го поема."},
   {"type":"scenario","title":"Изоставане от графика","question":"Екипът е с час назад преди последните три клипа. Какво правиш?","correct":"Преоценяваш критичните доставки, обявяваш промяна и пазиш QA/почивките.","wrong":["Махаш тестовете и копирането, за да запазиш план.","Ускоряваш говорещия и не казваш на клиента."],"feedback":"Коригирай плана видимо; не прехвърляй скрит риск към монтажиста."}
  ]},
 {"id":"pv08-16","title":"SOP за екипа: един процес, който нов колега може да повтори","minutes":44,
  "goal":"Ще опишеш производствения процес така, че следващ колега да го изпълни и да знае кога да спре и да поиска решение.",
  "hook":"Системата работи само докато авторът е на работа; при отпуск никой не знае кой одобрява, копира или сменя статуса.",
  "principle":"Стандартна процедура не е роман. Тя показва тригера, owner, входове, стъпки, критерий за готовност, stop condition и къде се записва доказателство. Добави един пример за нормален случай и един за отказ. Ако процедурата не може да се изпълни без автора, има скрито знание, което трябва да се изнесе в карту/образец.\n\nВерсията SOP има собственик и дата. Обновявай я след реален проблем, нов инструмент или изменение в клиентския процес. Не разчитай на screenshots от стар интерфейс като единствен източник; впиши какво се проверява дори ако менюто се премести.",
  "detail":"Пиши с действен глагол и видим резултат: „отвори проверения export и виж дали…“, а не „увери се, че е хубав“. За поверителни задачи посочи къде не се качва материал. Дай нов колега да изпълни процедурата без устно подсказване; всеки въпрос е сигнал за редакция.",
  "workflow":["Определи процес и момент, в който той започва и приключва.","Назначи owner и заместник; изброй необходими входове.","Опиши стъпките с проверки и резултат след всяка важна операция.","Добави stop condition при грешен файл, права, звук, липсващ approval или backup.","Посочи лог, шаблон и източник на актуални правила.","Дай на нов човек да повтори процеса; редактирай по реалните затруднения."],
  "case":"Нов редактор получава задача за клип. SOP показва къде са брифът, одобреният сценарий, proxy и master; дава правила за име и проверка на export. Редакторът спира, когато открие неподкрепено твърдение, и знае на кого да го върне.",
  "failure":"Процедурата казва само „експортирай финала и качи в папката“, без технически критерии, собственик или stop condition.",
  "fix":"Запиши вход, отговорник, действие, проверка, отказ и handoff; валидирай с човек извън екипа.",
  "practice":"Напиши кратка SOP за ingest, монтажен handoff или архив. Дай я на колега, който не е участвал в създаването, и отбележи всяко място, където му се налага да пита.",
  "acceptance":"Нов колега може сам да изпълни нормалния процес, да открие нарочен проблем и да знае на кого да го предаде.",
  "extras":[["Преглед на процедурата","На месечен преглед провери дали имената, инструментите, ролите и правата още са актуални. Отбележи версия и собственик."]],
  "questions":[
   {"type":"quiz","title":"Състав на SOP","question":"Кое прави кратката процедура приложима?","correct":"Тригер, owner, входове, стъпки, критерий, stop condition и място за доказателство.","wrong":["Дълго описание на идеалния случай.","Само списък с менюта на една версия на софтуера."],"feedback":"Процедурата трябва да помага и при отклонение, не само при идеални условия."},
   {"type":"scenario","title":"Неподкрепено твърдение","question":"SOP казва да публикуваш, но продуктова характеристика няма източник. Как действаш?","correct":"Спираш публикацията и връщаш твърдението към owner за потвърждение.","wrong":["Публикуваш, защото процесът те кара да продължиш.","Питаш генеративен инструмент да потвърди твърдението."],"feedback":"Stop condition има предимство пред автоматичното продължаване; източникът трябва да се провери."},
   {"type":"quiz","title":"Тествай SOP с нов човек","question":"Как разбираш, че инструкцията е достатъчна?","correct":"Човек извън автора я изпълнява без устни подсказки и улавя примерния отказ.","wrong":["Авторът я чете и намира за ясна.","Има много страници и screenshot-и."],"feedback":"Изпълнението от друг човек е реална проверка за скрито знание."},
   {"type":"scenario","title":"Софтуерът смени менюто","question":"Интерфейсът е обновен, а SOP има стар screenshot. Какво правиш?","correct":"Обновяваш инструкцията по целта и проверяваш стъпките в текущата версия.","wrong":["Оставяш я — опитният колега ще се оправи.","Добавяш още стари screenshot-и."],"feedback":"Поддържай резултата и критериите актуални, не само картинката от менюто."}
  ]}
]

M9A = [
 {"id":"pv09-01","title":"От брифа до предаване: работен ред за монтаж","minutes":48,
  "goal":"Ще подготвиш монтаж, който друг човек може да отвори, прегледа, поправи и предаде по брифа.",
  "hook":"Клипът изглежда завършен, но таймлайнът е от грешен формат, оригиналите липсват и няма записана версия за клиента.",
  "principle":"Монтажът започва с бриф, медия и технически изисквания — не с ефекти. Провери ориентация, кадрова честота, дължина, канал, субтитри, аудио, права и име на export. Организирай оригиналите, audio, graphics, project, proxies и output така, че всяка версия да е проследима.\n\nРедактирай на етапи: избор на кадри, rough cut по смисъл, финален ритъм, звук, цвят, графики, QA и предаване. Не коригирай цвят или шум до picture lock без причина, защото ще повториш работа. Експортът не е финал, докато не го отвориш и прегледаш целия файл.",
  "detail":"Преди импорт провери дали копието е пълно и дали файловете следват схемата. Направи project settings според брифа и източника; ако се налага преобразуване на честота, тествай движението. Сглоби кратък rough cut, после гледай с аудио, без аудио и на целевото устройство. Запиши решение и версия при всеки handoff.",
  "workflow":["Потвърди бриф, канал, версия, технически изход, права и одобрител.","Провери папки, име, цялост на медията, frame rate и нужда от proxy.","Създай проект с ясни bins и sequence; пази оригиналите неизменени.","Избери usable takes и сглоби rough cut по целта на клипа.","Финализирай ритъм, звук, корекция, текст и графики в отделни pass-ове.","Експортирай по спецификация, отвори файла, изгледай го и запиши handoff."],
  "case":"Фирма изпраща 40 клипа и иска 30-секундно видео за сайт плюс вертикална версия. Монтажистът първо потвърждава кадри в секунда и формати, после прави rough cut и проверява дали има кадри за двата aspect ratio. Не кропва автоматично целия проект, преди да види лицата и текстовете.",
  "failure":"Редакторът започва с музикален монтаж и ефекти, а след това открива, че ключовата реплика и форматът са различни от брифа.",
  "fix":"Потвърди спецификация, покритие и структура; изгради смислов монтаж, преди да полираш.",
  "practice":"Направи 20-секунден монтаж от 6–10 клипа. Запиши бриф, избор на дубъли, rough/final версии, настройки на sequence и бележка за предаване.",
  "acceptance":"Проектът отваря оригиналите, отговаря на формата, export-ът се гледа целия, а нов монтажист разбира коя версия е одобрена.",
  "source":"YouTube публикува актуални препоръки за кодиране и кадрова честота; ползвай спецификацията на канала от брифа: https://support.google.com/youtube/answer/1722171",
  "questions":[
   {"type":"quiz","title":"Преди ефектите","question":"Кое трябва да изясниш преди да започнеш таймлайна?","correct":"Бриф, източници, формат, кадрова честота, права и кой одобрява версията.","wrong":["Пакет преходи и LUT.","Само името на песента."],"feedback":"Техническите и съдържателните ограничения определят правилния проект."},
   {"type":"scenario","title":"Липсва ключова реплика","question":"След музикален монтаж виждаш, че основният отговор липсва. Какво правиш?","correct":"Връщаш се към брифа и rough cut-а, намираш usable дубъл и пренареждаш историята.","wrong":["Добавяш още ефекти, за да прикриеш липсата.","Предаваш клипа без основното послание."],"feedback":"Посланието трябва да работи преди украса."},
   {"type":"quiz","title":"Версия за предаване","question":"Кое означава финален export?","correct":"Файлът е по спецификация, отваря се, цял е прегледан и е обозначен с правилна версия.","wrong":["Прогресът на export стигна 100%.","Файлът носи думата final в името."],"feedback":"Провери резултата, не само приключването на рендер."},
   {"type":"scenario","title":"Две съотношения","question":"Клиентът иска 16:9 и 9:16, а важен текст е до ръба. Как постъпваш?","correct":"Правиш отделно прекомпозиране и проверяваш текста и лицата във всеки формат.","wrong":["Изрязваш автоматично центъра и експортираш двете версии.","Разтягаш 9:16 до широк формат."],"feedback":"Композицията се проверява в целевия кадър; не деформирай изображението."}
  ]},
 {"id":"pv09-02","title":"Ритъмът на сцената: режи по смисъл, не по таймер","minutes":39,
  "goal":"Ще редактираш кратък клип така, че всяка пауза, реакция и смяна на кадър да служат на смисъла.",
  "hook":"Монтажът сменя кадър на всеки две секунди, но зрителят не разбира действието и не усеща нито акцент, нито пауза.",
  "principle":"Ритъмът идва от намерението, съдържанието и реакцията, а не от универсална дължина на кадъра. Режи, когато зрителят е получил нужната информация или когато следващ кадър разкрива нещо ново. Пауза може да показва съмнение, усилие или завършено действие; премахването ѝ може да смени характера на човека.\n\nИзползвай разнообразие в план, гледна точка и действие само когато се чете. Ако сменяш кадъра без промяна в информацията, монтажът изглежда нервен. Гледай първо без музика; после добави музика и провери дали тя не диктува по-бърз ритъм от посланието.",
  "detail":"Маркирай моменти за избор: начало на мисъл, доказателство, реакция, преход и CTA. Остави достатъчно handle около движението. Използвай реакционен кадър, когато той носи смисъл, не за да прикрие лоша реплика. Къси монтажи не изискват всеки кадър да е кратък — при продуктова демонстрация зрителят трябва да види действието.",
  "workflow":["Определи едно основно действие или идея на клипа.","Гледай суровия материал и маркирай начало, завършек, пауза и реакция.","Сглоби версия без музика и провери дали историята се разбира.","Махай само повторения и празно време, което не носи намерение.","Добави разнообразен кадър при смислова промяна, не по фиксиран интервал.","Гледай със и без музика и сравни дали музиката не изкривява темпото."],
  "case":"Майстор показва как сменя велосипедна гума. Срезове се поставят между инструмент, движение и резултат; ключовото затягане остава достатъчно дълго да се види. Музиката се добавя тихо и не ускорява кадър преди действието да приключи.",
  "failure":"Всички паузи се изтриват и кадърът се сменя на равен интервал, без да се гледа смисълът.",
  "fix":"Изрежи по свършена мисъл или видимо действие; провери дали новият кадър носи допълнителна информация.",
  "practice":"Направи две 20-секундни версии от едни и същи клипове. Едната режи през две секунди, другата по смислови моменти; сравни разбираемостта и усещането.",
  "acceptance":"Зрителят може да опише действието след едно гледане; нито пауза, нито важна стъпка е премахната без причина.",
  "questions":[
   {"type":"quiz","title":"Режи по намерение","question":"Кога е добра точка за срез?","correct":"Когато зрителят е получил информацията или следващият кадър променя разбирането.","wrong":["След точно две секунди във всеки кадър.","Всеки път когато музиката има удар."],"feedback":"Ритъмът следва информацията и действието, а не само музикалния grid."},
   {"type":"scenario","title":"Демонстрацията е нечетлива","question":"Срезът маха стъпката, в която инструментът захваща детайла. Какво правиш?","correct":"Връщаш нужното време или добавяш близък кадър, за да се види причинно действие.","wrong":["Ускоряваш още повече за динамика.","Добавяш текст „готово“ върху неясния момент."],"feedback":"Монтажът трябва да позволи на зрителя да разбере физическото действие."},
   {"type":"quiz","title":"Пази смислова пауза","question":"Кога кратка пауза трябва да остане?","correct":"Когато показва реакция, дишане, колебание или завършване на мисълта.","wrong":["Никога; паузите са празно време.","Само ако има музикален акцент."],"feedback":"Пауза може да носи характер или смисъл."},
   {"type":"scenario","title":"Музиката натиска","question":"Музиката кара клипа да изглежда прибързан, а демонстрацията не се разбира. Какво правиш?","correct":"Преизграждаш ритъма по действието и избираш музика, която го подкрепя.","wrong":["Ускоряваш кадрите, за да съвпаднат с бийта.","Оставяш визуалното объркване, защото песента е популярна."],"feedback":"Първо ясна история; музиката следва, не заменя редакторското решение."}
  ]},
 {"id":"pv09-04","title":"Текст и субтитри, които не закриват картината","minutes":41,
  "goal":"Ще поставиш точни, четими надписи и субтитри в кадър, който е проверен на целевото устройство.",
  "hook":"Надписът е граматически верен, но закрива продукта; автоматичният транскрипт е сбъркал името на клиента.",
  "principle":"Текстът в кадър изпълнява конкретна задача: идентифицира човек, показва ключово число, подкрепя достъпността или дава CTA. Не повтаря всяка изговорена дума с огромен шрифт. Субтитрите трябва да са верни на речта и да се появяват навреме. Автоматичната транскрипция ускорява черновата, но имена, цифри, отрицания, пунктуация и жаргон се проверяват спрямо аудиото.\n\nПази важния текст в рамките на канала и тествай го в реален preview; интерфейсът може да закрива долната или страничната зона. Контрастът, размерът и редовете трябва да се четат на малък екран. Избери burn-in, sidecar или embedded captions според brief и възможността зрителят да ги включва.",
  "detail":"Направи текстов слой след финалното кадриране, не преди да смениш aspect ratio. Провери дължина на ред, време за прочит, имената, езика и дали субтитрите не дублират графика. За важен CTA остави кадър, в който продукт/лице не се закрива. Пусни файл на малък телефон със звук и без звук.",
  "workflow":["Определи дали текстът е титър, субтитър, число или CTA.","Генерирай чернова от аудио и сверявай редовете с оригиналния глас.","Подреди йерархия, размер, контраст и позиция за всеки формат.","Провери safe zones и елементи на платформата в целевия preview.","Експортирай правилния вид caption track според изискването.","Прегледай целия файл и провери имена, тайминг и скрито лице/продукт."],
  "case":"Видео с диетолог има 9:16 версия и субтитри на български. Автотранскриптът сбърква грамажа. Монтажистът сверява числото с одобрения източник, премества текста над зоната на интерфейса и проверява целия клип на телефон.",
  "failure":"Автоматичният текст се експортира без корекция и се поставя ниско в кадъра, където платформеният UI го покрива.",
  "fix":"Свери всяка реплика, провери safe zones на конкретния канал и изгледай export на истинския екран.",
  "practice":"Добави субтитри към 20 секунди говор. Внеси нарочно грешка в име или число, после я открий чрез сверка с аудио. Провери burn-in и отделен caption track, ако програмата ги поддържа.",
  "acceptance":"Всички думи и числа са потвърдени, надписът се чете на телефон и важен кадър остава видим във всеки формат.",
  "source":"Adobe показва генериране на транскрипт и safe margins; провери актуалните ръководства: https://helpx.adobe.com/premiere/desktop/add-text-images/insert-captions/auto-transcribe-video-using-speech-to-text.html ; https://helpx.adobe.com/premiere/desktop/get-started/source-and-program-monitor-adjustments/view-safe-zones-in-the-monitors.html",
  "questions":[
   {"type":"quiz","title":"Провери транскрипта","question":"Кои думи са особено важни за ръчна проверка?","correct":"Имена, числа, отрицания и термини, сверени спрямо аудиото и одобрените факти.","wrong":["Само първият ред на клипа.","Думи, които автоматиката е подчертала в зелено."],"feedback":"Малка грешка в число или отрицание може да обърне смисъла."},
   {"type":"scenario","title":"Текстът закрива продукта","question":"При preview на телефон субтитър покрива опаковката. Какво правиш?","correct":"Преместваш/прекомпозираш субтитъра в безопасно място и проверяваш всички формати.","wrong":["Свиваш текста, докато стане нечетим.","Оставяш го, защото на монтажния монитор се вижда."],"feedback":"Оцени позицията на реалния екран и интерфейса на канала."},
   {"type":"quiz","title":"Избери вид captions","question":"Кога burn-in е подходящ?","correct":"Когато брифът и каналът искат надписи винаги видими и стилът е проверен за кадъра.","wrong":["Винаги, независимо дали зрителят трябва да ги включва.","Когато текстът още не е редактиран."],"feedback":"Избери формат по изискване; вариантът не отменя точността."},
   {"type":"scenario","title":"Грешен грамаж","question":"В автоматичния субтитър има грешен грамаж. Как продължаваш?","correct":"Сверяваш аудиото и одобрения източник, поправяш текста и преглеждаш останалите числа.","wrong":["Оставяш го, ако изглежда реалистично.","Махаш единицата, за да не се вижда грешката."],"feedback":"Не гадай факти; проверявай числа преди предаване."}
  ]},
 {"id":"pv09-05","title":"Корекция на цвета преди творческата визия","minutes":47,
  "goal":"Ще изравниш експозиция и баланс на бялото, ще съпоставиш кадри и ще приложиш look без да рушиш детайла.",
  "hook":"LUT е нанесен върху всички клипове; кожата става оранжева, светлите части са изгорели, а различните камери вече не си приличат.",
  "principle":"Работи в ред: идентифицирай профила и color management, нормализирай източника, коригирай експозиция и баланс, съпостави кадри, после добави творческа визия. Log не е самостоятелен look — той изисква правилно преобразуване към пространството за изход. Не нанасяй един LUT без проверка върху различни обективи, лица и светлини.\n\nИзползвай scopes като помощ, но гледай и самото изображение на калибриран/надежден дисплей. Запази детайл в кожи, светли участъци и сенки. Смесената светлина може да изисква локална корекция или повторно осветяване; не всяка цветна разлика може да се поправи без артефакт.",
  "detail":"Първо провери source profile и timeline/output transform. Направи баланс на неутрална повърхност, после провери кожа и свързани кадри. Сравнявай frames едно до друго, не само по памет. Ако един кадър е свръхекспониран, изолирай го; не променяй целия timeline. Запиши node/layer имена, за да може колега да разбере корекцията.",
  "workflow":["Свери профил/гамут и целевия изход от camera note и брифа.","Настрой управлението на цвета и преобразуването за source.","Коригирай баланс на бялото и експозиция по scopes и образ.","Съпостави кадри, кожа и ключови цветове в сцената.","Добави creative look след correction; ограничи го, ако губи детайл.","Провери целия монтаж на надежден екран и сравни кадри при playback."],
  "case":"Интервю е снимано с телефон в Log и кадри от втора камера в стандартен профил. Монтажистът първо установява source профила, отделно преобразува Log, изравнява бялото и съпоставя лица. Едва след това добавя по-нисък контрастен look, който не унищожава детайлите.",
  "failure":"Един LUT се поставя без управление на цвета, а корекцията се прави по превюто на ярък телефон.",
  "fix":"Потвърди source profile и output transform, коригирай кадрите поотделно и провери на надежден дисплей.",
  "practice":"Коригирай два кадъра от една сцена и един с различна светлина. Направи преди/след сравнение, пази кожа и детайл в светлото, после добави умерен look.",
  "acceptance":"Кадрите от една сцена се съпоставят; няма изгорели важни участъци; source profile и look са записани за следващия редактор.",
  "source":"Официалният DaVinci Resolve разделя Color страницата и инструментите за корекция от creative look; свери актуалната документация: https://www.blackmagicdesign.com/products/davinciresolve/color",
  "questions":[
   {"type":"quiz","title":"Ред на цветова работа","question":"Кога прилагаш творческия look?","correct":"След като профилът, трансформацията, експозицията и балансът са проверени.","wrong":["Преди да провериш дали източникът е Log.","Едновременно върху всички проекти по подразбиране."],"feedback":"Корекцията възстановява нормална база; look е отделен творчески избор."},
   {"type":"scenario","title":"Оранжева кожа","question":"След LUT кожата е оранжева и детайлът в прозореца изчезва. Какво правиш?","correct":"Проверяваш profile/transform и намаляваш или махаш LUT преди ръчна корекция.","wrong":["Добавяш още топлина, за да изравниш фона.","Повишаваш наситеността на всички клипове."],"feedback":"Провери веригата и защити детайл; наслагването на ефекти не лекува грешно преобразуване."},
   {"type":"quiz","title":"Съпостави кадрите","question":"Как проверяваш две свързани сцени?","correct":"Гледаш ги една до друга и сравняваш кожа, експозиция, неутрални повърхности и основни цветове.","wrong":["Настройваш еднакви числови стойности на двата клипа.","Сверяваш само thumbnail от таймлайна."],"feedback":"Еднакви стойности не гарантират еднаква светлина или профил."},
   {"type":"scenario","title":"Смесена светлина","question":"Едната половина на лицето е от прозорец, другата от зелена лампа. Какъв е добрият ход?","correct":"Коригираш сцената/маскираш локално, ако е възможно, и пазиш естествен тон на кожата.","wrong":["Прилагаш един white balance към целия кадър и усилваш сатурацията.","Слагаш LUT с по-син нюанс върху всички сцени."],"feedback":"Смесеното осветление може да изисква локална работа; един глобален контрол може да влоши едната страна."}
  ]},
 {"id":"pv09-06","title":"Звук в монтажа: чист говор и измерен финал","minutes":44,
  "goal":"Ще подредиш диалога, room tone, музика и ефекти така, че посланието да остава разбираемо и да покрива delivery brief.",
  "hook":"На монтажния монитор музиката е приятна, но на телефон заглушава тихия отговор и една рязка дума изскача силно.",
  "principle":"Подреди звука по значимост: разбираем диалог, естествена среда, музика и ефекти. Поправи монтажни прекъсвания с room tone и чисти fades; ползвай EQ и компресия внимателно, след като отстраниш причина за шум. Гледай отделните канали и общия микс, защото два нормални клипа могат да се сумират твърде силно.\n\nНяма една универсална сила за всички платформи и договори. Използвай target от брифа и подходящ loudness meter, особено за podcast/broadcast deliverables. За социален клип слушай през слушалки, студийни монитори и обикновен телефон; провери mono compatibility. Не усилвай шум между репликите само за да запълниш тишината.",
  "detail":"Изравни диалог между дублите, направи fades при cut, пази естествената динамика и автоматизирай музиката около ключови думи. Провери пикове и Integrated loudness според конкретния стандарт. Ако няма target, поискай; не измисляй число и не приемай, че normalize автоматично дава готов микс.",
  "workflow":["Потвърди delivery target и кой файл/канал трябва да бъде чути.","Изолирай и подреди диалога; поправи очевидни прекъсвания и шумови пикове.","Добави room tone, после музика/ефекти на по-ниско ниво.","Автоматизирай нивото, за да остане говорът разбираем без постоянен максимум.","Измери loudness/peaks спрямо brief; провери клипинг и тишина.","Слушай целия export на телефон и слушалки; запиши измерване и версия."],
  "case":"Обяснителен клип има един тих дубъл и един силен. Монтажистът изравнява репликите, оставя room tone под cut-а и сваля музиката по време на важния термин. Loudness meter се настройва по зададената спецификация на клиента, а не по универсален интернет съвет.",
  "failure":"Музиката се нормализира силно, лимитерът се натиска и речта губи динамика и яснота.",
  "fix":"Изгради баланса от диалог навън, измери финала по зададен стандарт и провери на реални устройства.",
  "practice":"Смеси 20 секунди диалог с room tone и музика. Провери три устройства, маркирай шип/клипинг и измери target loudness според brief или избран тестов формат.",
  "acceptance":"Речта се разбира на телефон, няма клипинг или рязък cut, а финалното измерване отговаря на спецификацията и е записано.",
  "source":"Adobe Loudness Meter поддържа измерване и различни стандарти за различни доставки; избери target от брифа: https://helpx.adobe.com/premiere/desktop/add-audio-effects/apply-audio-effects/about-loudness-meter.html",
  "questions":[
   {"type":"quiz","title":"Пази разбираемия диалог","question":"В какъв ред е разумно да строиш микса?","correct":"Диалог и монтажни поправки, среда, после музика и ефекти.","wrong":["Музика до желания максимум, после диалог.","Ефекти и limiter преди да прослушаш суровата реч."],"feedback":"Диалогът носи основното послание; изгради другите слоеве около него."},
   {"type":"scenario","title":"Музиката заглушава думата","question":"Ключова дума изчезва при музикален удар. Какво правиш?","correct":"Автоматизираш/сваляш музиката и проверяваш речта на телефон.","wrong":["Повишаваш общия master output.","Слагаш още компресия, без да слушаш."],"feedback":"Подреди слоевете и провери четимостта на изговореното."},
   {"type":"quiz","title":"Избери target","question":"Какъв loudness target задаваш?","correct":"Посочения от канала или клиента; ако липсва, изясняваш го или документираш тестова цел.","wrong":["Едно число за всеки тип видео.","Колкото по-силно, толкова по-професионално."],"feedback":"Спецификациите се различават; измерителят проверява target, не го избира вместо теб."},
   {"type":"scenario","title":"Щракване на среза","question":"На пауза между изреченията се чува щракване. Как го поправяш?","correct":"Проверяваш cut точката, добавяш room tone и кратък fade без да режеш смисъла.","wrong":["Усилваш noise reduction върху целия клип.","Добавяш силен ефект точно върху щракването."],"feedback":"Първо почисти монтажната точка; избягвай обработка, която поврежда целия глас."}
  ]},
 {"id":"pv09-07","title":"Adjustment layers: общ ефект с контрол над изключенията","minutes":37,
  "goal":"Ще приложиш обща корекция върху серия кадри и ще изолираш кадрите, които изискват отделно решение.",
  "hook":"Една промяна в adjustment layer поправя повечето клипове, но съсипва нощния кадър и кожата в близкия план.",
  "principle":"Adjustment layer дава обща промяна върху кадри под него — например лек look, винетка, графика или общо кадриране. Той е бърз и неразрушителен само ако обхватът му е видим и изключенията са планирани. Някои корекции принадлежат към клипа, други към целия sequence; не слагай всичко на един слой.\n\nИменувай слоевете по функция, настройвай диапазона и маркирай изключения. Провери крайния кадър в началото, средата и края на покрития sequence. Ако клипът влиза под слой по невнимание, проблемът се появява чак в export.",
  "detail":"Раздели базова корекция на source clip от обща стилизация. Използвай отделен слой за текстура или look и още един, ако нужна графика трябва да стои над всички изображения. Запиши кое ниво влияе на кой кадър. За sequence с различни локации направи отделни group или локални adjustments.",
  "workflow":["Определи дали корекцията е за източник, група кадри или целия timeline.","Създай слой с точно име и постави го над желаните клипове.","Ограничи дължината/диапазона и провери кадрите под него.","Изключи или направи отделен вариант за кадър, който не понася ефекта.","Пусни sequence от начало до край, гледайки първи/средни/последни кадри.","Запиши слоя и зависимостите в project handoff."],
  "case":"Серия интервюта има обща леко топла визия. Един кадър е нощен и вече топъл. Общият layer прилага стил на всички, затова монтажистът изключва нощния insert и коригира локално, без да променя базата на останалата серия.",
  "failure":"Общият слой се простира извън sequence или съдържа едновременно цветове, текст и корекции без ясно име.",
  "fix":"Раздели функция, контролирай диапазон и провери кадрите в реалния playback.",
  "practice":"Направи общ слой за три кадъра, нарочно включи четвърти кадър с различна светлина, после изолирай изключението и запиши layer map.",
  "acceptance":"Друг редактор разбира кое се влияе от всеки слой; всички изключения са отбелязани и проверени в целия монтаж.",
  "questions":[
   {"type":"quiz","title":"Постави корекция на правилното ниво","question":"Кога adjustment layer е удобен?","correct":"Когато една контролирана промяна трябва да важи за ясно ограничена група кадри.","wrong":["Когато всеки кадър има различна цветова грешка.","Когато ефектът трябва да остане без име и граници."],"feedback":"Общ слой е ефективен само ако влиянието и изключенията са видими."},
   {"type":"scenario","title":"Нощният кадър се променя","question":"Общият look прави нощния кадър прекалено топъл. Какво правиш?","correct":"Изключваш или локално коригираш този кадър и проверяваш sequence-а отново.","wrong":["Намаляваш look-а за целия филм, без да гледаш останалите кадри.","Оставяш го, защото adjustment layer е общ."],"feedback":"Изключението може да се отдели; провери дали общата промяна още работи за останалата сцена."},
   {"type":"quiz","title":"Дай слой име","question":"Защо името на adjustment layer е важно?","correct":"Показва функцията и помага на колега да разбере обхват и зависимост.","wrong":["За да спечелиш точки в timeline.","За да замени notes и проверка."],"feedback":"Надписът е част от четимостта на проекта; документацията пак е нужна за сложни зависимости."},
   {"type":"scenario","title":"Ефектът свършва по средата","question":"Export-ът показва, че ефектът спира на неочакван кадър. Какво проверяваш?","correct":"Дължината и позицията на слоя и playback целия sequence.","wrong":["Само настройката на последния клип.","Променяш резолюцията на проекта."],"feedback":"Грешен диапазон е проблем на timeline организацията; проследи слоя от начало до край."}
  ]},
]

M8A = [
 {"id":"pv08-01","title":"Пакетно производство: планирай месец без обещания за чудеса","minutes":44,
  "goal":"Ще превърнеш месечна нужда от видеа в снимачен обхват, който екипът може да произведе и провери.",
  "hook":"Планът обещава 15 клипа за ден, но пропуска подготовка, паузи, повторения, импорт и проверка.",
  "principle":"Пакетното снимане събира сходни настройки и намалява повторната подготовка; то не премахва писане, съгласие, редакция или одобрение. Брой клипове се определя от формата, трудността, броя участници, локациите и средния брой дубъли. Вечнозелено съдържание може да се снима предварително, но оферти, срокове, цени и актуални факти имат дата на валидност.\n\nПланирай работата назад от готовите доставки: колко видеа, кои версии, кой одобрява и кога. Остави резерв между сетовете. Ако редакторът и единствен оператор са един човек, предвиди и време за работа след снимките.",
  "detail":"Вземи реалните данни от последните няколко проекта: подготовка на един клип, време за смяна на говорещ, повторения и процент кадри, които се връщат за поправка. Използвай медианата, не най-добрия ден. Планирай няколко различни структури, за да не звучат всички клипове еднакво; групирай по локация и осветление, но пази почивките.",
  "workflow":["Определи месечните доставки и отбележи кои факти или оферти изтичат.","Групирай по локация, човек, светлина и комплект, не само по тема.","Сметни setup, запис, средни повторения, почивка и техническа проверка.","Резервирай време за монтаж, обратна връзка, корекция и резервен снимачен слот.","Потвърди участници, одобрители, права и всички твърдения преди деня.","Измери на следващия ден какво е заснето, годно и действително предадено."],
  "case":"Малък фитнес публикува три пъти седмично. Вместо да обещае 12 клипа за ден, екипът групира осем вечнозелени упражнения и оставя четири слота за сезонни теми. Реалните данни показват, че снимачният ден поема осем клипа с един треньор, включително паузи и повторения.",
  "failure":"Планът брои само минутите пред камерата и третира всеки клип като еднакво сложен.",
  "fix":"Измери целия работен цикъл и определи брой клипове по реални минути и сложност.",
  "practice":"Направи план за осем клипа с поне две различни структури. За всеки отбележи валидност на фактите, локация, участник, време за запис, нужни дубли и кой ще одобри.",
  "acceptance":"Графикът съдържа setup, почивки, тестове, буфер и отделен монтаж; временните твърдения имат дата или слот близо до публикуването.",
  "questions":[
   {"type":"quiz","title":"Планирай по реален капацитет","question":"Кое е надеждна основа за броя клипове в batch деня?","correct":"Реално време за подготовка, дубъли, смяна на сет, паузи и проверка от сходни проекти.","wrong":["Дължината на клиповете на публикация.","Най-бързият ден, който екипът някога е имал."],"feedback":"Капацитетът се измерва по целия цикъл, не само по говоренето пред камера."},
   {"type":"scenario","title":"Актуална оферта","question":"Един от клиповете съдържа цена, която може да се промени след седмица. Как го планираш?","correct":"Отбелязваш валидността и заснемаш близо до одобрението/публикацията или планираш повторен дубъл.","wrong":["Слагаш го в библиотеката за месеци без дата.","Премахваш датата, за да не личи промяната."],"feedback":"Партидното производство не превръща твърдение с ограничен срок във вечнозелено."},
   {"type":"quiz","title":"Един снимачен ден ≠ месец монтаж","question":"Какво остава извън сметката, ако планираш само времето пред камера?","correct":"Подготовка, одобрение, ingest, монтаж, QC, корекции и предаване.","wrong":["Нищо, защото видеата вече са записани.","Само качването на клиповете в социална мрежа."],"feedback":"Доставката е целият процес от бриф до приет файл."},
   {"type":"scenario","title":"Графикът закъснява","question":"След третия сет вече сте с час назад. Кой ход е професионален?","correct":"Преоценяваш обхвата, пазиш критичните клипове и съгласуваш преместване на останалите.","wrong":["Изтриваш паузата и QC, за да снимаш всичко.","Продължаваш без да предупредиш клиента."],"feedback":"Промени графика прозрачно; не прикривай риск за качество и безопасност."}
  ]},
 {"id":"pv08-02","title":"Осем сценария предварително: разнообразие с одобрени факти","minutes":40,
  "goal":"Ще подготвиш сценарии с различни гледни точки, доказани твърдения и ясна следваща стъпка.",
  "hook":"Осмият клип повтаря първия с различен фон; екипът е снимал обем, но не и разнообразно съдържание.",
  "principle":"Сценарият преди снимачния ден намалява чакането и помага да се запише точният кадър. Започни от нуждата на зрителя, избери едно проверимо твърдение и добави доказателство или демонстрация. Редувай формати: отговор на въпрос, процес, преди/след, грешка, кратък разбор, покана. Не превръщай всички теми в еднакви hook–три точки–CTA.\n\nЗа всеки сценарий пази източника на фактите, одобрителя и срока им. Забранени твърдения не се „омекотяват“ до маркетингово обещание; ако доказателство липсва, сценарият се връща за уточнение. Запиши и какво зрителят трябва да види, за да не остане клипът само говореща глава.",
  "detail":"Карточката за всеки видео-сценарий съдържа: аудитория, една цел, доказан факт, сцена/показване, задължителна формулировка, риск от двусмислие и CTA. Маркирай реплики, които изискват отговор от клиент. Остави едно поле за дата или промяна, ако условието не е постоянно.",
  "workflow":["Събери осем въпроса, възражения или действия от реални клиенти.","Подреди ги по нужда и избери осем различни формата.","За всяко твърдение добави източник, дата и одобрител.","Пиши за говор, после прочети на глас и махни повторенията.","Свържи репликата с кадър, предмет, действие или екранна демонстрация.","Постави сценарии с актуални условия в слот близо до публикуването."],
  "case":"Онлайн магазин за велосипеди има осем клипа: настройка на седалка, проверка на гуми, избор на размер, демонстрация на спирачка и четири често задавани въпроса. Един клип споменава гаранция; текстът се одобрява от отговорника и носи дата на валидност.",
  "failure":"Сценаристът копира едно и също заглавие и призив във всичките осем текста, без да провери факти или аудитория.",
  "fix":"Промени ъгъла според реалния въпрос и остави доказателство, собственик и CTA за всеки сценарий.",
  "practice":"Напиши четири различни сценария за една услуга: отговор, демонстрация, честа грешка и клиентски процес. Отдели фактите от мнението и отбележи кой ги одобрява.",
  "acceptance":"Всяка карта има едно послание, доказуемо твърдение, кадър, CTA, одобрител и дата, когато твърдението може да остарее.",
  "questions":[
   {"type":"quiz","title":"Факт преди формулировка","question":"Нямаш източник за обещан резултат. Какво правиш?","correct":"Спираш твърдението и го връщаш за проверка или го заменяш с потвърден факт.","wrong":["Добавяш „обикновено“ и го публикуваш.","Питаш модела да намери убедителна формулировка."],"feedback":"По-мек тон не създава доказателство."},
   {"type":"scenario","title":"Един и същи hook","question":"Осем сценария звучат като копия. Кое подобрение има най-голям смисъл?","correct":"Свързваш темите с различни въпроси и сцени от реални клиенти.","wrong":["Сменяш само цветовете на надписите.","Добавяш по един силен прилагателен израз към всеки."],"feedback":"Разнообразието идва от въпрос, доказателство и формат, не от синоними."},
   {"type":"quiz","title":"Карта за снимачния ден","question":"Кое поле помага да се заснеме сценарият, не само да се прочете?","correct":"Какво действие, предмет или екран зрителят трябва да види.","wrong":["Само дължината на текста.","Цветът на фона, без връзка с темата."],"feedback":"Кадърът трябва да показва причината зрителят да повярва."},
   {"type":"scenario","title":"Променлива гаранция","question":"Условие по гаранцията може да се промени. Как подготвяш клипа?","correct":"Проверяваш официалния текст, посочваш одобрител и дата, после планираш актуален слот.","wrong":["Снимаш общо обещание, без срок и одобрение.","Използваш текста от миналогодишната кампания."],"feedback":"Условията и датата са част от достоверността на клипа."}
  ]},
 {"id":"pv08-03","title":"Непрекъснатост между дни: светлина, цвят, дрехи и позиция","minutes":38,
  "goal":"Ще направиш различни записи да изглеждат като една серия, като документираш това, което реално може да се повтори.",
  "hook":"Двата кадъра на едно интервю са от различни дни: цветът на кожата, прозорецът и позицията на предметите се разминават.",
  "principle":"Непрекъснатостта не означава да заключиш всеки кадър до един и същ preset. Тя означава да запазиш важните зрителски сигнали: ос, поглед, ниво на камерата, посока на светлина, баланс на бялото, дрехи и състояние на продукта. Запиши референтен кадър и бележка при първата смяна на сет.\n\nАко светлината или локацията са се променили, направи нов тест и не компенсирай на сляпо в монтажа. Сравнявай кожа, фон и обект при еднакъв монитор. Отбележи преднамерените разлики като част от историята — например преди/след — вместо случайна промяна.",
  "detail":"Полезната continuity карта записва дата/час, позиция и височина на камерата, обектив/режим, баланс на бяло, светлинни източници, място на реквизита, дреха и действия. Снимай референтна снимка на сет без лични данни. При повторен ден възпроизведи само важните условия; не преследвай еднакъв вид, ако това вреди на новия кадър.",
  "workflow":["Определи кои елементи трябва да изглеждат свързани между кадрите.","Маркирай позиция на камера, стол, продукт и източници на светлина.","Запиши камера настройките и направи референтен кадър с кожа и неутрална повърхност.","При следващ снимачен ден подреди сет по бележката и сравни тестов кадър.","Провери ос, поглед, дреха, реквизит и ключовата светлина.","Запиши и обясни неизбежната разлика; не я скривай с автоматичен preset."],
  "case":"Фризьорски салон снима три стъпки от една прическа в различни часове. Екипът маркира позицията на стола, височината на телефона, ръката на стилиста и светлината. Дневната светлина се промени; следващият тест пази посоката на лицето и използва еднаква ключова лампа.",
  "failure":"Екипът пази само настройките на камерата и забравя, че слънцето, дрехите и предметите се променят.",
  "fix":"Документирай и физическия сет, после направи тест кадър при повторното заснемане.",
  "practice":"Създай continuity карта за серия от три клипа. Снимай референция, прибери реквизита и опитай да възстановиш кадъра на следващия ден.",
  "acceptance":"Вторият дубъл запазва гледна точка, основна светлина и състояние на предмета; отклоненията са отбелязани и умишлени.",
  "questions":[
   {"type":"quiz","title":"Какво запазва continuity картата","question":"Кое е нужно освен настройките на телефона?","correct":"Позиции на камера/човек/реквизит, светлина, дреха и референтен кадър.","wrong":["Само името на приложението.","Само филтърът за цвят."],"feedback":"Повторяемостта включва сцената и физическите позиции, не само менюто на камерата."},
   {"type":"scenario","title":"Светлината се е променила","question":"На следващия ден прозорецът е в пряко слънце. Какво правиш?","correct":"Правиш нов тест и запазваш посоката на сцената чрез контролируема светлина или преместване.","wrong":["Копираш вчерашните настройки и продължаваш.","Понижаваш експозицията, без да гледаш кожата."],"feedback":"Повтори намерението на светлината, не механично всяка стойност."},
   {"type":"quiz","title":"Преднамерена разлика","question":"Кога разлика между кадрите е полезна?","correct":"Когато е умишлена и помага на зрителя да разпознае промяна или действие.","wrong":["Когато е случайна и се прикрива с филтър.","Когато балансът на бялото се сменя без причина."],"feedback":"Непрекъснатостта служи на историята; умишленото преди/след може да е ясно различно."},
   {"type":"scenario","title":"Преместен продукт","question":"В повторния кадър продуктът е завъртян, а рекламата трябва да показва същия етикет. Какво правиш?","correct":"Възстановяваш ориентацията по референтния кадър и записваш нов тест заедно с ключовото действие.","wrong":["Оставяш го, защото монтажът може да обърне картината.","Изрязваш етикета от кадър."],"feedback":"Сравни референтната позиция и потвърди, че важната маркировка остава видима."}
  ]},
 {"id":"pv08-04","title":"Графикът на снимачния ден: снимай по сет, пази енергията","minutes":38,
  "goal":"Ще подредиш снимачния ред според смени на локация и техника, без да изтощиш хората и да загубиш кадри.",
  "hook":"Екипът сменя осветление за всеки клип, прескача от стая в стая и губи час в пренареждане.",
  "principle":"Групирай сходните задачи по място, човек, светлина и оборудване, но не превръщай актьора или клиента в производствена машина. Снимай най-важните сцени, когато екипът е свеж; остави възстановяване, вода и буфер след блокове с много повторения. Ако дреха или реквизит трябва да се смени, пази реда по последователност.\n\nНай-краткият маршрут невинаги е най-добрият график. Предвиди шум на локацията, достъп, паркиране, естествена светлина, разрешения и срок за връщане на техника. Промяната в графика трябва да обнови списъка с кадри и да бъде видима за продуцента и клиента.",
  "detail":"Работи в блокове: пристигане/осмотр, светлинен тест, кратък сет, серия кадри, проверка, почивка, смяна, финален копиращ период. За интервю вземи звука преди да изградиш сложен кадър. Ако човекът е нужен само за две сцени, планирай прозорец, но не оставяй най-трудната реплика за последните минути.",
  "workflow":["Отбележи локации, хора, реквизит, достъп и часове на естествена светлина.","Сгрупирай кадрите по най-малко смени на сет и ясно обозначи нужната дреха/реквизит.","Започни с критичните кадри, които са трудни за повторение.","Добави паузи и резерв между блоковете; не планирай непрекъснат запис.","Провери заснетите кадри при всяка смяна и премести липсващото, докато е възможно.","Изпрати обновен ред и статус на участниците и монтажиста."],
  "case":"Една организация снима кадри на рецепция, в кабинет и на открито. Вместо шест пътувания, екипът снима всички сцени в кабинета, после рецепцията и накрая външния план преди залез. Ключовото интервю е в първия блок, когато специалистът е свободен.",
  "failure":"Кадрите се подреждат по номер на готовите видеа, макар това да означава многократно разглобяване на един и същ сет.",
  "fix":"Организирай по локация и настройки; пази отделно кои са задължителните кадри във всеки клип.",
  "practice":"Направи график за една локация и три сета. Впиши блок за транспорт/пренареждане, почивки, най-критичен кадър, одобрение и финална проверка.",
  "acceptance":"Графикът показва къде и кога се сменя сет, кой трябва да е на място, буфера и ред за повторение.",
  "questions":[
   {"type":"quiz","title":"Подреди по зависимости","question":"Какво определя най-ефикасния ред на кадрите?","correct":"Сет, хора, локация, светлина, достъп и критичност за проекта.","wrong":["Номерът на клипа в месечния календар.","Редът, в който сценариите са написани."],"feedback":"Организирай заснемането по реалната цена на смяната и риска."},
   {"type":"scenario","title":"Гостът има само 20 минути","question":"Ключовият интервюиран е на разположение кратко. Какво правиш?","correct":"Подготвяш сет предварително, тестваш звук/светлина и снимаш критичната реплика в договорения прозорец.","wrong":["Оставяш интервюто за последно след всички декоративни кадри.","Махаш теста, за да започнеш по-рано."],"feedback":"Подготовката преди пристигане пази времето на човека и качеството на кадъра."},
   {"type":"quiz","title":"Защо има буфер","question":"Какво покрива буферът между снимачни блокове?","correct":"Промяна на сет, шум, повторен дубъл и реални прекъсвания.","wrong":["Допълнителна дължина на клипа.","Възможност за пропускане на копие и QA."],"feedback":"Буферът е план за вариация, не свободно време за неограничен обхват."},
   {"type":"scenario","title":"Един сет се забавя","question":"Първият блок закъснява, а слънцето ще залезе. Какъв е приоритетът?","correct":"Снимаш външния кадър, който зависи от светлината, и съгласуваш останалия ред.","wrong":["Продължаваш по стария ред независимо от светлината.","Премахваш проверката на записаното."],"feedback":"Пренареди зависимия кадър и съобщи промяната на екипа."}
  ]},
 {"id":"pv08-05","title":"Колко материал поема екипът: измери капацитета, не го гадай","minutes":39,
  "goal":"Ще изчислиш реален производствен капацитет и ще покажеш къде забавя целият процес.",
  "hook":"Камерата снима бързо, но монтажът, обратната връзка и липсващите файлове правят екипа неспособен да предаде обещания обем.",
  "principle":"Капацитетът е брой приети доставки за даден период, не броят заснети дубъли. Измери време по роли: сценарий, подготовка, снимане, ingest, чернова, проверка, корекция и предаване. Добави процент за повторно заснемане и клиентски отговор. Верига спира на тесния участък: ако монтажът отнема два дни, по-бърза камера няма да утрои изхода.\n\nИзползвай данни от няколко седмици и разделяй типове задача. Не смесвай 15-секундни talking head клипове със събитие, анимация или multi-camera интервю. Капацитетът трябва да пази качество и работно време, не да доказва, че екипът може да работи без почивка.",
  "detail":"Следи три числа: планирани минути, действителни минути и годни/приети клипове. Добави причина за отклонение: забавено одобрение, технически проблем, ново изискване, повторна корекция. Сметни медианата и разброса по тип работа. Продавай обещание според устойчивия темп, не според най-добрия ден.",
  "workflow":["Раздели доставките по сложност и канал.","Запиши време по фаза и роля за няколко реални проекта.","Отдели чакането от активната работа, но запиши срок за обратна връзка.","Считай само приети файлове; запиши повторни снимки и поправки.","Намери фазата с най-много забавяне или грешки.","Промени един процесс, измери отново и провери, че качество не е паднало."],
  "case":"Монтажистът довършва 12 клипа месечно, а екипът планира 20. Данните показват, че половината време отива в неясни клиентски бележки и повторно експортиране. Нов лимит на ревизиите и фиксиран бриф повишават изхода повече от покупка на по-бърз компютър.",
  "failure":"Сметката включва само минути на запис и пренебрегва post, корекции, одобрения и повторения.",
  "fix":"Мери целия процес до приет файл; промени тесния участък, после отново измери резултата.",
  "practice":"Води лог за три работни дни. Запиши активното време, чакането, броя приети клипове, върнатите поправки и причината. Изчисли устойчив седмичен капацитет.",
  "acceptance":"Предложен капацитет има данни, разделя типове работа, съдържа резерв и не прикрива чакащи клиентски одобрения.",
  "questions":[
   {"type":"quiz","title":"Мери крайния резултат","question":"Кое е най-добро измерване на производителността?","correct":"Приети доставки за период, с време и корекции по фази.","wrong":["Брой заснети клипове без преглед.","Брой часове, в които камерата е включена."],"feedback":"Само приетият продукт затваря веригата."},
   {"type":"scenario","title":"Монтажът е тесният участък","question":"Снимането изпреварва монтажа. Какво е разумното първо действие?","correct":"Измерваш причините в монтажа и корекциите; временно коригираш броя доставки или добавяш капацитет там.","wrong":["Купуваш нов телефон и обещаваш повече клипове.","Скъсяваш всеки монтаж, без да питаш клиента."],"feedback":"Надгради тесния участък; нова скорост другаде не променя общия поток."},
   {"type":"quiz","title":"Сравнявай сходно със сходно","question":"Как да изчислиш типично време за монтаж?","correct":"Групирай сходни формати и използвай няколко наблюдения с медиана и разброс.","wrong":["Използвай най-бързия случай от всички формати.","Събери всички проекти, независимо от сложността."],"feedback":"Различните задачи имат различни стъпки и трябва да се измерват отделно."},
   {"type":"scenario","title":"Клиентът чака три седмици","question":"Половината срок се губи в отговор от клиента. Как го отчиташ?","correct":"Записваш чакането, задаваш срок за обратна връзка и коригираш обещаната дата според зависимостта.","wrong":["Изключваш чакането от плана и запазваш старата дата.","Правиш промени без одобрение, за да не чакаш."],"feedback":"Зависимостта трябва да е видима за клиента и да влияе на графика."}
  ]},
 {"id":"pv08-06","title":"Монтажен поток за серия: шаблонът помага, но не взема решения","minutes":41,
  "goal":"Ще превърнеш една серия от клипове в повторяем монтажен процес със специфична проверка за всеки епизод.",
  "hook":"Шаблонът ускори сглобяването, но постави грешното име върху продукта и музиката заглушава единствената важна реплика.",
  "principle":"Шаблонът трябва да стандартизира повтарящи се настройки, цветове, лога и позиции; той не решава историята, акцента, точността или етиката. Направи базов проект с чиста таймлайн структура, стилове, графики и име на версия. Дублирай проекта за нов епизод, не презаписвай приключен клиентски файл.\n\nЗа всяка версия провери специфични имена, факти, ритъм, субтитри, цветови кадри, нива на говор и CTA. Ако формата или профилът на проекта се сменя, направи нов шаблон, вместо да добавяш изключения, които никой не разбира.",
  "detail":"Принимай една смяна в шаблона отговорно: копие, версия, кратка бележка и тест на един клип. Запази изходен вариант без графики. Използвай маркери за одобрение и финални кадри, за да не разчиташ на цвят на папка или памет. Обновявай шаблон между проектите.",
  "workflow":["Създай чист проект с фреймрейт, цветово управление и аудио структура от брифа.","Подреди bins за видео, аудио, графики, проксита, проекти и експорти.","Добави повторяеми графики, но остави място за индивидуални кадри и надписи.","Направи копие на проекта за епизода и свържи оригиналните медии.","Редактирай по смисъл и провери фактите и ефекта по всеки клип.","Експортирай с име/версия и пусни QC; върни поправките в отделна версия."],
  "case":"Видеосерията на клиника използва еднакъв начален знак и надпис за специалист. В нов епизод се сменя лекарят, услугата и юридическата бележка; монтажистът дублира шаблона, обновява само данните и проверява звук, кадър и точен текст.",
  "failure":"Проектът от минал клиент се презаписва; старият телефонен номер и цветова настройка попадат в новия файл.",
  "fix":"Дублирай базов проект за всяка поръчка и използвай клиентски QA лист, който проверява конкретни променливи.",
  "practice":"Създай шаблон за три кратки клипа. Направи отделни копия, смени имена и CTA, после използвай чеклист, който открива една нарочно поставена стара информация.",
  "acceptance":"Всеки епизод има отделен проект и версия; стар текст/име не остава, а брифът и проверките се намират в папката.",
  "questions":[
   {"type":"quiz","title":"Стандартизирай повторяемото","question":"Какво е добра задача за шаблон?","correct":"Постоянни технически настройки, шрифтове и позиции, които са одобрени за серията.","wrong":["Решение за най-добрия дубъл във всеки епизод.","Автоматично избиране на факти и клиентски твърдения."],"feedback":"Шаблонът пази консистентност, не замества редакторска преценка."},
   {"type":"scenario","title":"Стар номер върху графика","question":"В новия клип се появява телефонът от предишния клиент. Какво правиш?","correct":"Спираш предаването, коригираш източника и графиката, после преглеждаш всички изходи от серията.","wrong":["Покриваш номера с надпис само в един клип.","Надяваш се, че текстът е твърде малък за четене."],"feedback":"Провери изходния проект и всички версии, не само видимия кадър."},
   {"type":"quiz","title":"Проект или export","question":"Защо нов епизод започва от копие на шаблона?","correct":"Пази базата и историята на предишните проекти, като изолира новите имена и медии.","wrong":["За да използваш чужда медия без да я копираш.","За да обединиш всички клипове в една времева линия."],"feedback":"Отделният проект ограничава случайни промени и помага на следващ редактор."},
   {"type":"scenario","title":"Клиент сменя цветовете","question":"Клиентът одобрява нова цветова тема за серията. Как я внедряваш?","correct":"Копираш шаблона, документираш версията и тестваш промяната върху един клип преди останалите.","wrong":["Презаписваш базата преди да провериш четливостта.","Променяш само един епизод, без да кажеш на екипа."],"feedback":"Провери промяната и обнови версията, преди да стане стандарт."}
  ]},
 {"id":"pv08-07","title":"Публикационен календар: кой одобрява, какво изтича и какво е готово","minutes":37,
  "goal":"Ще изградиш календар за видео, който отразява реални състояния, срокове, отговорници и зависимост от клиента.",
  "hook":"Клипът е в календара със статус „готов“, но все още чака одобрение и съдържа старо работно време.",
  "principle":"Календарът не е списък от дати. Той показва тема, канал, версия, срок, отговорник, одобрител, права и състояние. Използвай ясни състояния като идея, сценарий за проверка, одобрен за снимане, заснет, монтаж, клиентски преглед, одобрен, насрочен и публикуван. Не маркирай одобрен без доказателство или запис на човека, който е одобрил.\n\nАктуални цени, промоции, локации и сезонни правила трябва да имат валидност. Публикационен слот за тях се планира близо до проверката. Подготви резервна тема, ако фактите не могат да бъдат потвърдени навреме; не оставяй календара да притиска екипа към догадки.",
  "detail":"За всяка публикация има финален файл, текст, миниатюра, линк към правата или източника, формат, субтитри, дата/час и процедура за сваляне или корекция. Не допускай два човека да приемат, че другият ще публикува. След публикация провери действителния пост и запиши URL.",
  "workflow":["Създай колони за активност, собственик, одобрител и статус.","Свържи всяка тема с канал и конкретен формат/версия.","Отбележи твърдения с дата, права, срокове и клиентски dependencies.","Задай срок за одобрение и автоматично видим статус при закъснение.","Преди насрочване свери файл, текст, CTA, формат, права и финална версия.","След публикация отвори действителния пост, запиши адрес и коригирай календара."],
  "case":"Ресторант планира клип за меню, което се сменя в петък. Фактът е проверен в четвъртък сутрин и има отговорник за цени. Ако потвърждението не дойде, резервната evergreen тема за кухнята замества клипа; календарът пази причината.",
  "failure":"Календарът съдържа само дата и тема, затова никой не вижда изчакващи одобрения или изтекло съдържание.",
  "fix":"Управлявай състояния, собственик, версия и валидност; насрочвай само одобрен файл.",
  "practice":"Изгради седмица за две платформи с осем публикации. Включи собственик, одобрител, готов файл, валидност на фактите, резервна публикация и поле за URL след публикуване.",
  "acceptance":"Няма планирано съдържание без одобрител, потвърден файл и ясна отговорност за публикуването.",
  "questions":[
   {"type":"quiz","title":"Какво значи готово","question":"Кога календарът може да постави клип в статус „одобрен“?","correct":"Има записан одобрител и конкретната версия, която е приета.","wrong":["Монтажистът е изпратил първи export.","Клипът изглежда добре на телефона на оператора."],"feedback":"Одобрението се отнася за конкретна версия, не за обща идея."},
   {"type":"scenario","title":"Изтичаща оферта","question":"Клип с промоция е планиран за след две седмици, а срокът на офертата е неизвестен. Какво правиш?","correct":"Проверяваш срока и отговорника, иначе заменяш слота с проверено съдържание.","wrong":["Публикуваш и добавяш малък disclaimer.","Оставяш цену без дата."],"feedback":"Календарът трябва да спре изтекъл или непотвърден факт."},
   {"type":"quiz","title":"Затвори публикационния цикъл","question":"Какво записваш след публикация?","correct":"Действителния URL, време и финалната версия, за да може екипът да провери резултата.","wrong":["Само отметка, че календарът е попълнен.","Новата тема за следващия месец."],"feedback":"Проверката след publish потвърждава, че правилният файл стигна до правилния канал."},
   {"type":"scenario","title":"Двама мислят, че другият публикува","question":"Клипът е одобрен, но в деня на публикация няма собственик. Какво променяш?","correct":"Назначаваш един отговорник за публикуване и резервен, после проверяваш реалния пост.","wrong":["Оставяш задачата в общата група без име.","Маркираш публикацията като направена предварително."],"feedback":"Един собственик на следващото действие премахва двусмислието."}
  ]},
 {"id":"pv08-08","title":"Име на файл, което колегата може да разбере","minutes":30,
  "goal":"Ще направиш правила за име и версия, които помагат на екипа да намери оригинал, проект и правилен export.",
  "hook":"В папката има final.mp4, final_new.mp4, final2.mp4 и final_final2.mp4; никой не знае коя е одобрената версия.",
  "principle":"Името трябва да отговаря на практичните въпроси: клиент/проект, дата или кампания, формат/език, версия и състояние. Избери разделител и правило за версия, което е лесно за сортиране и не разчита на умалителни като „ново“ или „последно“. Името на проекта и папките трябва да съвпада с работната система, за да не се разкача медията.\n\nНе използвай лични данни в публични линкове, които не са нужни за работа. За оригиналните имена запази карта или manifest, ако клиентът/камерата изисква непроменени файлове. Вземи съгласие на екипа и създай примерни имена преди да преименуваш партида.",
  "detail":"Полезен pattern може да е Client_Project_Date_Channel_Language_Version_Status.ext; адаптирай полетата към екипа и каналите. Номерирай версии последователно, записвай финалност отделно и не преименувай файл след като е свързан към монтажен проект без relink тест.",
  "workflow":["Изброй въпросите, на които файлът трябва да отговори без отваряне.","Избери постоянни полета, ред, разделител и правила за празно поле.","Определи версия, одобрение и формат; забрани имена като final-final.","Създай именувани примери за raw, project, proxy и export.","Приложи правилото първо към копия и провери сортиране и relink.","Обучи екипа; запиши owner на схемата и процедурата за промяна."],
  "case":"Три монтажисти предават вертикални реклами на клиент. Новото правило включва клиент, кампания, дата, формат, език, версия и status; оригиналите запазват номера на камерата, а CSV manifest връзва оригинал с монтажния asset.",
  "failure":"Преименуваш клипове на камерата след монтаж и пътищата в проекта сочат към несъществуващи файлове.",
  "fix":"Преименувай на ingest или използвай manifest; пробвай relink на копие преди серийна промяна.",
  "practice":"Измисли 12 файла: raw, аудио, проект, proxy и два изхода на два езика. Приложи схема и помоли колега да намери одобрената версия без обяснение.",
  "acceptance":"Друг човек намира клиент, проект, формат, език и одобрена версия само от името и папката.",
  "questions":[
   {"type":"quiz","title":"Име за екип","question":"Кое име най-полезно различава финалните файлове?","correct":"Съгласувани полета за клиент, проект, формат, език, версия и статус.","wrong":["final-new-last.mp4.","Кратко име, което разбира само авторът."],"feedback":"Стандартизираното име прави версиите филтруеми и разбираеми."},
   {"type":"scenario","title":"Проектът offline","question":"След преименуване на raw файловете монтажът не намира медиата. Какво правиш?","correct":"Възстановяваш пътя или relink-ваш по manifest върху копие, после проверяваш клиповете.","wrong":["Изтриваш offline items и започваш отначало.","Преименуваш и проекта до същото заглавие."],"feedback":"Нужна е връзка между старите имена и новите пътища; поправи контролирано."},
   {"type":"quiz","title":"Пази оригиналния контекст","question":"Какво правиш с имената на камерните файлове?","correct":"Запазваш ги или водиш проверим manifest, който свързва оригинал с работното име.","wrong":["Преименуваш директно картата по памет.","Премахваш номерата, за да са имената кратки."],"feedback":"Оригиналният ID помага при повторно копиране и проверка на източника."},
   {"type":"scenario","title":"Две финални версии","question":"Клиентът одобри вариант на английски, но има и български export. Как различаваш?","correct":"Включваш език, формат, версия и статус в името според общото правило.","wrong":["Пишеш final_en и final_bg без да посочиш проект и версия.","Записваш върху единия файл."],"feedback":"Езикът и статусът са различни измерения; пази ги заедно с версия и проект."}
  ]}
]

M7B = [
 {"id":"pv07-09","title":"Комплект до 300 €: поправи първо най-слабата връзка","minutes":35,
  "goal":"Ще разпределиш малък бюджет според реалните проблеми в снимането, без да купуваш техника за чужд бриф.",
  "hook":"Нова камера е купена, но интервютата продължават да звучат далечно и файловете се губят между приложенията.",
  "principle":"До 300 € не купувай камера, преди да знаеш какво пречи на сегашната. За разговор често най-голямата полза е близък микрофон; за статична демонстрация — устойчива опора; за лице до прозорец — отражател или подходяща лампа. Остави бюджет за кабели, карта, адаптер и резерв.\n\nЦените се сменят. Сравнявай общата цена с доставка, съвместимост, гаранция и бъдеща употреба. Не приемай, че евтино значи лошо или че скъп аксесоар ще пасне на телефона.",
  "detail":"Подреди ограниченията по щета и честота. Ако звукът се проваля на всяко интервю, микрофонът може да спести повече от нова лампа. Ако интервютата са стабилни, но няма копие, носителят е по-важен от ефектен аксесоар. Запиши три реални задачи от следващия месец и свери покупката с тях.",
  "workflow":["Опиши три типа видеа и най-честия технически проблем във всяко.","Избери един bottleneck, който пречи на годен материал или губи време.","Сравни телефон, микрофон, опора, светлина, носител и адаптери по съвместимост и обща цена.","Остави резерв за доставка, кабел или ремонт; не харчи сумата на хартия.","Пробвай наем, заем или тестов комплект, ако съвместимостта е неясна.","Повтори същия кадър след покупката и измери какво се подобри."],
  "case":"Самостоятелен треньор снима уроци у дома. Проблемът е отекващият глас и треперещ телефон, а прозорецът дава достатъчно светлина. Планът дава приоритет на микрофон, стойка и правилен адаптер; LED панелът отпада, докато тестът не покаже нужда.",
  "failure":"Купува се камера, защото спецификациите изглеждат професионално, без бюджет за оптика, звук, опора и запис.",
  "fix":"Похарчи първо за доказан bottleneck и провери ефекта със същия кадър преди и след покупката.",
  "practice":"Направи три кошници: нужно днес, полезно при конкретен вид работа и засега ненужно. За всяка покупка запиши съвместимост, цена с адаптери, решаван проблем и тест на ефекта.",
  "acceptance":"Списъкът има проблем, доказателство, обща цена и тест на резултата; бюджетът пази резерв.",
  "questions":[
   {"type":"quiz","title":"Къде отива бюджетът","question":"Нямаш пари за всичко. Как подреждаш покупките?","correct":"По риска за използваемия материал и честотата, с която проблемът се появява.","wrong":["По реда на новите модели в магазина.","Първо купуваш най-скъпия компонент за бъдещето."],"feedback":"Измерим bottleneck показва къде вложението може да върне време или качество."},
   {"type":"scenario","title":"Камера или микрофон","question":"Кадърът е приемлив, но клиентите връщат клип за неясен говор. Какво проверяваш?","correct":"Микрофон, адаптер, място и мониторинг с реален запис.","wrong":["Камера с повече мегапиксели.","Добавяш субтитри, без да поправиш звука."],"feedback":"Повтори проблема и избери покупката, която отстранява причината."},
   {"type":"quiz","title":"Сметни цялата покупка","question":"Кое сравнение е пълно?","correct":"Устройство, адаптери, стойка, захранване, доставка, гаранция и връщане.","wrong":["Само цената на корпуса.","Броят функции, отпечатани на опаковката."],"feedback":"Аксесоар без съвместима връзка или монтаж е неизползваем."},
   {"type":"scenario","title":"Офертата изтича","question":"Не знаеш дали стойката пасва, а отстъпката важи само днес. Какво правиш?","correct":"Проверяваш размер, товароносимост и връщане; пропускаш покупката, ако съвместимостта е неясна.","wrong":["Купуваш, защото отстъпката е по-важна от теста.","Поръчваш два модела без да планираш връщане."],"feedback":"Спешността не е техническо доказателство; съвместимостта и условията са част от цената."}
  ]},
 {"id":"pv07-10","title":"До 700 €: надгради само онова, което вече ползваш","minutes":38,
  "goal":"Ще планираш следващото ниво на мобилен комплект и ще провериш дали покупката спестява време в повтаряща се работа.",
  "hook":"Аксесоарите се наслагват; телефонът е тежък, батерията не стига и никой не е тествал комплекта като система.",
  "principle":"До 700 € можеш да увеличиш надеждността, но всяка част трябва да служи на повтарящи се задачи. Затвори пропуските в базовия комплект: мониторинг, съвместима опора, захранване, място и светлина, която не трепти при настройките ти. Не купувай функции, които телефонът вече изпълнява.\n\nИзчисли общото тегло, времето за сглобяване и броя работни дни. Аксесоар, който спестява пет минути веднъж на тримесечие, може да не оправдава цената. Остави основен комплект, който можеш да носиш сам.",
  "detail":"Направи проба с пълната сборка: държач, микрофон, лампа, батерия, кабели и кейс. Телефонът трябва да се завърта вертикално и хоризонтално без да изпуска връзка или да закрива камера. Провери дали зарядното внася шум; записвай с финалната сглобка, не с отделен аксесоар.",
  "workflow":["Събери реалните записи и отбележи забавянията и отказите.","Избери един надграждащ компонент и резерв, които решават тези проблеми.","Сглоби всички части и провери вертикална и хоризонтална конфигурация.","Запиши с включено и изключено захранване; сравни звук и нивомер.","Времи сглобяване, прехвърляне и смяна на режим.","Сравни обща цена с наем за следващите шест месеца."],
  "case":"Агенция прави четири интервюта седмично и иска втори микрофон. Тестът показва, че текущият звук е годен, а истинското забавяне е прехвърляне към лаптопа. Бюджетът първо отива в сигурен ingest и резервен носител.",
  "failure":"Към телефона се добавят лампа, клетка, батерия и приемник, без тест за достъп до портове, баланс и шум.",
  "fix":"Провери целия риг във всички планирани ориентации и при реално захранване.",
  "practice":"Направи бюджет до 700 € за един работен тип. Сравни покупка, наем и сегашния комплект за шест месеца; добави време за настройка, транспорт, кабели и ремонт.",
  "acceptance":"Всяка покупка решава посочен проблем, общата сума остава под лимита с резерв, а ригът минава тест за звук, ориентация, захранване и време.",
  "questions":[
   {"type":"quiz","title":"Оцени възвръщаемостта","question":"Кога има смисъл да надградиш компонент?","correct":"Когато повтарящ се проблем се измерва и новото устройство подобрява достатъчно реални задачи.","wrong":["Когато моделът току-що е излязъл.","Когато колега го е купил."],"feedback":"Ползата се оценява по употреба, време и разход, не по новост."},
   {"type":"scenario","title":"Ригът губи порт","question":"При завъртане към вертикал кабелът на приемника се измъква. Какво правиш?","correct":"Променяш маршрута на кабела или монтажа, после тестваш ориентация и звук.","wrong":["Залепяш конектора по време на интервюто.","Снимаш само хоризонтално, без да кажеш на клиента."],"feedback":"Критичните връзки трябва да работят в очакваните ориентации и движение."},
   {"type":"quiz","title":"Не плащай два пъти","question":"Какво предшества покупка на втори микрофон?","correct":"Проверка дали сегашният микрофон и прехвърлянето му работят за видовете задачи.","wrong":["Покупка на втори приемник без тест.","Намаляване на качеството, докато чуеш записа."],"feedback":"Затвори настоящия bottleneck, после оцени нуждата от резерв."},
   {"type":"scenario","title":"Захранването внася шум","question":"При зареждане в звука има брум. Какво правиш?","correct":"Сравняваш със захранване изключено, проверяваш кабел и адаптер, избираш чиста конфигурация.","wrong":["Вдигаш шумопотискането и приемаш резултата.","Скриваш кабела, без нов тест."],"feedback":"Промяната на захранване променя аудио веригата; тествай финалния комплект."}
  ]},
 {"id":"pv07-11","title":"До 1500 €: резерв и цена на използваемия клип","minutes":43,
  "goal":"Ще превърнеш среден бюджет в надежден комплект с резервен план и реалистична цена на продукцията.",
  "hook":"Екипът има добър телефон и микрофон, но едно повредено гнездо отменя цял снимачен ден.",
  "principle":"На това ниво бюджетът трябва да купи надеждност, не само спецификация. Разгледай резервен запис, втори носител, батерия, кабел и защитен транспорт. Първо подсигури частите, чиято повреда спира цялата работа.\n\nИзчисли цена на използваем клип: подготовка, снимане, монтаж, транспорт, лицензи, амортизация и поправки. При рядка употреба наемът може да е по-добър от покупка. При седмични задачи стандартният комплект спестява време, но провери съвместимост при обновяване на телефон или приложение.",
  "detail":"Задай граница за преносимост и човекочасове. Постави резерв в отделна чанта и провери, че екипът знае как да го използва. Картите и батериите са консумативи; не ги планирай до пълния капацитет. Фърмуер се обновява между проекти, не точно преди платена снимка.",
  "workflow":["Изчисли снимачните дни за 12 месеца и цената на наем за същия период.","Начертай веригата и огради единичните точки на отказ.","Избери резерв за най-скъпото прекъсване и предвиди място, захранване и поддръжка.","Назначи кой тества, зарежда и връща всеки компонент.","Проведи репетиция с основния и резервния маршрут.","Изчисли цена на използваем клип и актуализирай офертата си."],
  "case":"Медийно студио снима пет интервюта месечно. Рискът е липса на резерв при прекъснал запис. Част от бюджета остава за втори аудио маршрут и носители; камерата за редки външни кадри се наема според поръчката.",
  "failure":"Целият бюджет отива за корпус, но няма резервен аудио маршрут, копие или план за наем.",
  "fix":"Раздели сумата на основна система, критичен резерв, транспорт/съхранение и поддръжка.",
  "practice":"Сметни комплект до 1500 € за интервю, продуктова снимка и събитие. Отбележи общото оборудване, наемните позиции, резервната точка, употребата и хода при отказ.",
  "acceptance":"Всяка задача има основен и резервен път за звук и запис; сметката е под лимита и отчита цена на използваем резултат.",
  "extras":[["Планирай подмяната","Запиши за всяка батерия, карта и кабел по какво ще познаеш, че трябва да излезе от работа. Не чакай повредата да е на локацията."]],
  "questions":[
   {"type":"quiz","title":"Изолирай риска","question":"Кое трябва да получи резерв първо?","correct":"Компонент, чиято повреда спира поръчката и няма лесна замяна.","wrong":["Аксесоар, който подобрява кадъра, но не е нужен.","Най-новият елемент."],"feedback":"Резервирай най-скъпия отказ, не най-видимата покупка."},
   {"type":"scenario","title":"Едно USB-C гнездо","question":"Портът на телефона отказва по време на интервю. Как спасяваш работата?","correct":"Преминаваш към предварително тестван резервен запис и проверяваш синхрона.","wrong":["Включваш всеки адаптер от чантата, докато нещо проработи.","Продължаваш без микрофон и обещаваш да чистиш звука."],"feedback":"Резервният маршрут трябва да е изпитан и да запазва използваем диалог."},
   {"type":"quiz","title":"Купи или наеми","question":"Кога наемът заслужава предпочитание?","correct":"Когато техниката е нужна рядко, специфична е и пълният наем струва по-малко от притежанието.","wrong":["Когато наемът не изисква тест.","Винаги, защото собствената техника се износва."],"feedback":"Сравни доставка, обучение, застраховка и риск, не само цената за ден."},
   {"type":"scenario","title":"Обновяване преди клиента","question":"Приложението предлага голяма актуализация вечерта преди снимките. Какво правиш?","correct":"Оставяш работната система непроменена до края на проекта и тестваш новата отделно.","wrong":["Инсталираш, защото новата версия може да подобри камерата.","Обновяваш само телефона, без да тестваш приложението."],"feedback":"Променяй стабилна конфигурация в тестов прозорец, не преди платена снимка."}
  ]},
 {"id":"pv07-12","title":"Над 5000 €: купи работна система, не витрина","minutes":48,
  "goal":"Ще защитиш голяма инвестиция чрез натоварване, нужди на екипа, наем и срок на използване.",
  "hook":"Купена е професионална камера, но никой не може да настрои цвета, да копира медията и да върне проекта на монтажиста.",
  "principle":"Голям бюджет оправдава стандартизирана система, когато обемът и клиентските изисквания я налагат. Определи кой снима, записва звук, копира материал, монтира и одобрява. После избери съвместими камера, оптика, звук, светлина, носители, захранване, транспорт и мониторинг. Купи това, което използваш често; специфичната оптика или рекордер може да се наемат.\n\nПредвиди поддръжка, батерии, калибрация, обучение, съхранение и ремонт. Цветовият профил има стойност, ако постпродукцията може да го обработи и клиентът приема изхода. Голяма сума не отстранява липсата на дисциплина.",
  "detail":"Преди покупка тествай процеса с нает комплект: снимане, синхрон, копиране, монтаж, цветова корекция и експорт. Провери рендер, място, общо тегло, цена на монтажен ден и време за подготовка. Направи демонстрация с критерии за приемане, а не само със спецификация от каталога.",
  "workflow":["Събери последните 10 брифа и извлечи общите изисквания към кадър, звук и срок.","Раздели задължителните възможности от редките нужди, които ще наемаш.","Наеми пилотния комплект и изпълни задача с реалния екип и софтуер.","Запиши време за подготовка, копиране, рендер и предаване; събери проблемите.","Сметни общата цена за няколко години и сравни с наем, ремонт и обучение.","Вземи решение с бюджет, собственик, резерв и процедура за обновяване."],
  "case":"Студио продава месечни пакети интервюта и продуктови клипове. Екипът наема две конфигурации за месец: една с допълнителна цветова корекция и една мобилна. След сравнение на клиентския резултат, монтажа и носителите купува само често използвания комплект.",
  "failure":"Камерата е избрана по динамичен диапазон, без разход за оптика, логистика, съхранение и монтажен капацитет.",
  "fix":"Тествай наетата система през целия процес и сравни цената с приход, натоварване и клиентски изисквания.",
  "practice":"Подготви инвестиционна бележка за техника над 5000 €: поръчки, наем срещу покупка, пълна цена за три години, капацитет, резерви и критерий за отказ.",
  "acceptance":"Инвестицията има измерена употреба; целият процес е тестван, има отговорник и план за ремонт или наем при отказ.",
  "questions":[
   {"type":"quiz","title":"Система преди спецификация","question":"Какво стои начело на инвестиционното решение?","correct":"Повтарящите се изисквания на брифовете и хората, които ще снимат, монтират и предават.","wrong":["Най-високият динамичен диапазон в бюджета.","Две камери, които изглеждат еднакво в каталога."],"feedback":"Системата включва хора и прехвърляне на медия, не само камера."},
   {"type":"scenario","title":"Неподготвен Log","question":"Наетата камера записва Log, но монтажът няма цветово управление, а клиентът иска бърз файл. Какво правиш?","correct":"Ползваш тестван профил или първо подготвяш и тестваш целия процес за цветова корекция.","wrong":["Оставяш плоския Log образ за финал.","Вдигаш наситеността на око при експорта."],"feedback":"Суровият профил има стойност, когато монтажната верига може да го обработи."},
   {"type":"quiz","title":"Пълният разход","question":"Кой разход често липсва в първата сметка?","correct":"Оптика, носители, батерии, транспорт, ремонт, калибрация, обучение и монтажен капацитет.","wrong":["Само цената на шрифта за титри.","Нищо: производителят включва всичко в корпуса."],"feedback":"Цената на системата надвишава цената на основното тяло."},
   {"type":"scenario","title":"Рядък обектив","question":"Обективът трябва два пъти годишно, а наемът включва тест и застраховка. Какво сравняваш?","correct":"Общата цена на притежание и реалната честота спрямо целия разход за наем.","wrong":["Купуваш го, защото бюджетът трябва да се похарчи.","Отказваш наем без да сметнеш монтажния ефект."],"feedback":"Избери по употребата и общите разходи, не по размера на бюджета."}
  ]},
 {"id":"pv07-13","title":"Карта не е архив: копирай и провери преди изтриване","minutes":37,
  "goal":"Ще защитиш суровия материал с подредено копиране и ясно правило кога носителят може да се освободи.",
  "hook":"Папката на лаптопа има само част от клиповете, но картата вече е форматирана за следващия снимачен ден.",
  "principle":"Карта в камерата е работен носител, не архив. Копирай цялата структура, провери броя файлове или използвай checksum при ingest, после направи независимо копие на друг носител. Правилото 3-2-1 е отправна точка, но копията трябва да се проверяват и възстановяват.\n\nНе форматирай оригинала, докато копието не е проверено и отворено. Облачният sync може да прехвърля изтривания, затова провери версионирането и сроковете. Достъпът, шифроването и периодът на съхранение също са част от клиентската безопасност.",
  "detail":"Остави оригиналните имена или веди таблица, която свързва имена и нови названия; не преименувай карта по файл. При checksum сравни отчет на източник и копие. Ако такъв инструмент липсва, провери количество, размери и клипове от началото, средата и края. Измери и колко време отнема целият трансфер.",
  "workflow":["Маркирай картата като оригинал и спри запис след снимането.","Копирай цялата структура в папката по стандарта на проекта.","Пусни checksum или сравни отчета за брой и размер на файловете.","Отвори избрани клипове от копието и провери звук, картина и дължина.","Направи второ копие на отделен физически носител и отбележи мястото.","Форматирай само след потвърждение и според срока за съхранение."],
  "case":"Сватбен оператор снима цял ден на две карти. В края папките се копират на SSD, checksum отчетът съвпада и клипове от церемонията и вечерта се отварят. Второто копие се пази отделно; картите остават заключени до повторна проверка.",
  "failure":"Drag-and-drop приключва, на лаптопа се вижда папка и картата се форматира.",
  "fix":"Провери файловете на целевия носител, направи отделно копие и освободи картата само след приемане.",
  "practice":"Подготви папка с 20 смесени файла. Копирай я на два носителя, направи checksum или сравнение на размери, отвори произволни файлове и запиши кое копие е отделено от работния компютър.",
  "acceptance":"Има две копия на различни физически носители, проверка, отчет за място и известен срок и отговорник за съхранение.",
  "source":"CISA препоръчва offline копия и редовна проверка за възстановяване: https://www.cisa.gov/stopransomware/ransomware-guide",
  "extras":[["Проба за възстановяване","Възстанови един клип в празна тестова папка, отвори го и запиши колко време отнема и кой може да повтори процеса."]],
  "questions":[
   {"type":"quiz","title":"Кога да форматираш","question":"Кое трябва да е вярно преди изтриване на оригиналната карта?","correct":"Копието е проверено, клипове се отварят и има независим резерв според правилата на проекта.","wrong":["На лаптопа се вижда папка със същото име.","Копирането приключи без съобщение."],"feedback":"Успешният прозорец за копиране не доказва, че материалът се възстановява."},
   {"type":"scenario","title":"Не съвпада броят","question":"Копието има по-малко клипове от картата. Какво правиш?","correct":"Спираш форматирането, проверяваш отчета и липсващите пътища, после повтаряш копието.","wrong":["Форматираш — вероятно са дубликати.","Копираш само избраните миниатюри."],"feedback":"Несъответствието е стоп-сигнал; запази оригинала, докато го обясниш."},
   {"type":"quiz","title":"Разбери 3-2-1","question":"Какво описва 3-2-1?","correct":"Три копия, на два типа носител, с едно извън основното място.","wrong":["Три папки на една карта и две копия на същия SSD.","Три версии на монтажа без сурови клипове."],"feedback":"Различните носители и физическото разделяне намаляват общия риск."},
   {"type":"scenario","title":"Sync не е архив","question":"Облачният sync предава и изтривания. Какво добавяш?","correct":"Отделно версионирано или offline копие и периодичен тест за възстановяване.","wrong":["Наричаш sync папката архив.","Изключваш локалното копие, защото облакът е извън офиса."],"feedback":"Синхронизацията не винаги пази предишно състояние; провери retention и restore."}
  ]},
 {"id":"pv07-14","title":"Избери опора според кадъра: статив, монопод или гимбъл","minutes":33,
  "goal":"Ще избереш опора според дължината на записа, движението, пространството и нуждата от повторяем кадър.",
  "hook":"Тежък гимбъл се настройва за десетсекунден неподвижен кадър, а стативът стои в багажника за интервю от час.",
  "principle":"Стативът дава повторяем кадър и освобождава ръцете; моноподът помага при дълго снимане и честа смяна на позиция; гимбълът е за контролирано движение; ръката е бърза и естествена, но иска стабилна стойка и кратък дубъл. Няма универсален победител.\n\nПровери товар, височина, повърхност, захват и ориентация. На открито защити статива от вятър; в тълпа не оставяй крака в пътя на хората. За неподвижен обект първо пробвай опора, която изисква най-малко настройка.",
  "detail":"За интервю провери кадъра след няколко минути и дали стативът провисва. За монопод тествай опора към тялото и колко дълго задържаш кадъра. За гимбъл провери баланс, мотор и свободен маршрут. Времето за смяна на опора влиза в офертата и графика.",
  "workflow":["Определи дали кадърът стои, следва човек или променя гледната точка.","Оцени продължителността и колко често се сменя позицията.","Провери стабилност, товар, ориентация и безопасно пространство.","Репетирай монтаж и демонтаж с телефона и кейса.","Запиши кратък тест и го изгледай преди цялата сцена.","Използвай най-простата опора, която покрива задачата."],
  "case":"В болничен коридор има кратко интервю и ходене на специалист. Интервюто е на статив; после се заснема къс ръчен проход. Гимбълът остава за по-широк маршрут, където има пространство и реална нужда от движение.",
  "failure":"Една опора се използва за всички сцени, без оглед на дължината, движението и безопасността на публиката.",
  "fix":"Направи матрица кадър–опора. Тествай една сцена с два подхода и избери този, който намалява риска и работата.",
  "practice":"Избери фиксиран продукт, интервю от 30 секунди и движение през врата. За всеки посочи опора, време за настройка, риск за околните и критерий за приемане.",
  "acceptance":"Обясняваш защо опората пасва и монтираш телефона безопасно, без да закриваш камера или управление.",
  "questions":[
   {"type":"quiz","title":"Най-простата опора","question":"Какво е добро начало за дълго интервю без движение?","correct":"Статив, който дава повторяем кадър и не пречи на звука и погледа.","wrong":["Гимбъл, защото моторът спира всяко движение.","Телефонът върху коляното."],"feedback":"Опората трябва да отговаря на задачата, не да внася сложност."},
   {"type":"scenario","title":"Пътят е зает","question":"Краката на статива заемат път в оживена зала. Какво правиш?","correct":"Преместваш снимането или избираш по-безопасна опора и освобождаваш прохода.","wrong":["Оставяш статива и молиш гостите да го заобикалят.","Намаляваш височината без проверка на стабилността."],"feedback":"Безопасността на хората е част от избора на кадър и опора."},
   {"type":"quiz","title":"Разграничи монопода","question":"Къде моноподът може да е практичен?","correct":"При дълго снимане с честа смяна на позиция, когато стативът пречи.","wrong":["Когато камерата трябва да стои сама без оператор.","Когато е нужно механично плавно движение по маршрут."],"feedback":"Моноподът помага за опора и бърза смяна, но не замества статив или гимбъл."},
   {"type":"scenario","title":"Несигурна стойка","question":"Стойката едва удържа телефона и се накланя при докосване. Как постъпваш?","correct":"Не я използваш; проверяваш товароносимостта и вземаш съвместима опора.","wrong":["Снимаш, стига да не докосваш телефона.","Добавяш тежест отгоре без проверка на основата."],"feedback":"Нестабилната опора рискува техника, кадър и хора; не компенсирай неизвестен товар."}
  ]},
 {"id":"pv07-15","title":"Телепромптер без скрито четене: текст, поглед и темпо","minutes":34,
  "goal":"Ще превърнеш написан текст в естествено изпълнение, което говорещият произнася ясно.",
  "hook":"Водещият гледа право в обектива, но гласът е равен и очите препускат през думи, които не би казал в разговор.",
  "principle":"Телепромптерът помага за последователен текст, не замества изпълнението. Редактирай за говор: една идея на изречение, ясни паузи, произносими имена и продължителност, която пасва на кадъра. Постави текста близо до обектива, после провери движението на очите.\n\nСкоростта се наглася към човека, не обратното. Прочети на глас без камера, отбележи писмените фрази и замени ги с естествени. Ако говорещият се спъва, скъси изречението. Заснеми няколко реда и гледай без звук: лицето пак ли изглежда естествено?",
  "detail":"Подреди абзаците като смислови части и маркирай паузи, усмивка или показване на предмет. Шрифтът трябва да е четим от работното разстояние; редовете да не изискват широко движение на очите. Репетирай темпо с обикновен таймер, а не с дълго четене на екран. Остави водещия да повтори трудните думи преди дубъл.",
  "workflow":["Прочети текста на глас и измери реалната продължителност.","Замени писмени фрази, дълги изречения и неизговорими съкращения.","Раздели текста на дишаеми части и отбележи паузи и действия.","Постави текста близо до обектива и нагласи четим шрифт и скорост.","Запиши кратка проба и изгледай очите, темпото и естествените паузи.","Снимай по смислови части и отбелязвай използваемите дубъли."],
  "case":"Собственик на клиника трябва да обясни нова услуга за 45 секунди. Писменият бриф е два пъти по-дълъг. Монтажистът запазва фактите, маха повторенията, разделя обяснението на три мисли и задава телепромптера на темпо, при което говорещият може да вдигне поглед.",
  "failure":"Скролът е ускорен, за да побере целия дълъг текст; операторът чака водещият да се справи.",
  "fix":"Редактирай текста за реч, запази задължителните факти и заснемай на кратки смислови части.",
  "practice":"Вземи 120 думи от бриф, прочети ги, скъси до нужната дължина и отбележи паузи. Заснеми тест с и без телепромптер; сравни поглед и естественост.",
  "acceptance":"Водещият произнася ключовото твърдение точно, погледът е близо до обектива и времето пасва на договорената дължина.",
  "questions":[
   {"type":"quiz","title":"Направи текста говорим","question":"Водещият постоянно се спъва в дълги изречения. Какво променяш първо?","correct":"Съкращаваш и разделяш фразите, като запазваш потвърдените факти.","wrong":["Ускоряваш скрола, за да завърши по-бързо.","Намаляваш размера на текста."],"feedback":"Текстът трябва да се произнася естествено; скоростта не поправя писмен стил."},
   {"type":"scenario","title":"Фактът не се побира","question":"Клиентският бриф е 90 секунди, но договорът иска 45. Какво правиш?","correct":"Съкращаваш повторенията, пазиш задължителните факти и потвърждаваш съкратения вариант.","wrong":["Ускоряваш водещия до неестествено темпо.","Премахваш важно условие без клиентско потвърждение."],"feedback":"Олекоти текста, не променяй смисъла или условията по предположение."},
   {"type":"quiz","title":"Постави текста разумно","question":"Кое разположение намалява видимото четене?","correct":"Текстът е близо до обектива, а редовете и шрифтът са четими от позицията на водещия.","wrong":["Екранът стои далеч встрани, но шрифтът е много голям.","Текстът превърта по-бързо от говорещия."],"feedback":"Разстоянието и хоризонталното движение на очите се проверяват в реален кадър."},
   {"type":"scenario","title":"Грешка в репликата","question":"Водещият греши една дума в изречение с важни условия. Как продължаваш?","correct":"Спираш, сверяваш одобрения текст и снимаш цялата мисъл наново с чисто начало и край.","wrong":["Поправяш думата с надпис, който променя изговореното.","Оставяш дубъла, защото смисълът ти е ясен."],"feedback":"Не маскирай промяна на факт; осигури точен дубъл или потвърди редакцията."}
  ]},
 {"id":"pv07-16","title":"Преди да тръгнеш: приемане на снимачния ден","minutes":50,
  "goal":"Ще затвориш снимачна поръчка с покрит материал, проверен звук, копия, имена и ясно предаване към монтаж.",
  "hook":"Всички прибират техника, но никой не знае кой файл е добрият, какво остава за pickup и дали клиентът има право да използва музиката.",
  "principle":"Снимачният ден не е приключил, когато камерата е прибрана. Той приключва, когато всеки кадър от брифа има статус, ключовият материал е одитиран, копието е потвърдено и следващият човек знае какво да прави. Запиши имена и номера на добрите дубъли; отбележи проблем, липса на съгласие или неизпълнено условие.\n\nНе обещавай, че целият материал е добър, ако не си проверил. Подреди копието и предай кратка бележка: цел, формат, имена, отворени въпроси, права и срок. При чувствителен запис уточни кой има достъп и кога ще бъде изтрит.",
  "detail":"Преди разглобяване провери кадри, звук и технические дубли, после съгласие и права за хора, музика, локация и марки. Прехвърли картите, сравни имената и отвори тестови клипове. Определи дали има pickup и кой го одобрява. Не форматирай карта, докато копието и отговорникът не са потвърдени.",
  "workflow":["Свери всеки ред от брифа с клип и статус: готов, повторение, липсва.","Прослушай избраните реплики и провери ключовия кадър на голям екран.","Отбележи номера на добрите дубли, резервите и кадрите за pickup.","Провери права, съгласие и материал, който изисква ограничен достъп.","Копирай, сверѝ броя файлове и отвори клипове от целевото място.","Изпрати монтажисту структура, бриф, срок, версия и оставащи решения."],
  "case":"Клиентът иска интервю и три кадъра на продукта. Интервюто е заснето, но едно продуктово действие липсва. Вместо да изпратиш общ статус „готово“, отбелязваш липсата, предлагаш кратък pickup и предаваш монтажната част със списък на проверените дубли.",
  "failure":"Екипът казва „материалът е готов“, макар един от кадрите да липсва, а копието да не е проверено.",
  "fix":"Раздели приключилата работа от отворените задачи. Подкрепи статуса с кадри, файлове и отговорник.",
  "practice":"Направи приемателна бележка за един учебен снимачен ден: бриф, заснети кадри, избрани дубли, технически проблеми, права, копие, нужни pickup-и, получател и срок.",
  "acceptance":"Друг монтажист може да намери най-добрите дубъли и да започне работа, без да пита кое е записано или къде е копието.",
  "source":"За безопасно предаване на медията използвай и правилото за проверени offline копия на CISA: https://www.cisa.gov/stopransomware/ransomware-guide",
  "extras":[["Чеклист за екипа","Преди да напусне локацията, всеки член потвърждава една зона: камера и звук, права и съгласия, копиране и предаване."]],
  "questions":[
   {"type":"quiz","title":"Какво значи приключен ден","question":"Кога снимачният ден е готов за монтаж?","correct":"Когато брифът е сверен с кадри, ключовият материал е проверен и копието/бележката са предадени.","wrong":["Когато камерата е прибрана.","Когато всички са съгласни, че снимаха достатъчно."],"feedback":"Приключването се доказва с материал и предаване, не с усещане."},
   {"type":"scenario","title":"Липсва кадър","question":"От брифа липсва близък план, а локацията все още е достъпна. Какво правиш?","correct":"Записваш липсата и снимаш pickup, докато реквизитът и мястото са готови.","wrong":["Казваш на монтажиста да направи цифрово приближение от друг кадър.","Изпращаш статуса „готово“."],"feedback":"Повтори кадър, ако това е по-надеждно от изкуствена поправка."},
   {"type":"quiz","title":"Монтажистът получава контекст","question":"Кое трябва да има в краткото предаване?","correct":"Структура, номера на добрите дубли, бриф, ограничения/права, срок и отворени въпроси.","wrong":["Само линк към папка.","Общото „най-добрите кадри са някъде вътре“."],"feedback":"Бележката трябва да премахва търсенето и да предупреждава за решения."},
   {"type":"scenario","title":"Искат да изтрият картата","question":"Клиентът иска картата веднага за друга задача, но копието още не е проверено. Как реагираш?","correct":"Обясняваш риска и приключваш проверката или осигуряваш друг носител преди изтриване.","wrong":["Форматираш, защото клиентът го е поискал.","Копираш само избраните клипове, без да го отбележиш."],"feedback":"Ясно назови риска и направи прехвърлянето проверимо."}
  ]}
]

M9B = [
 {"id":"pv09-08","title":"Proxy без изгубен оригинал: монтаж и възстановяване","minutes":40,
  "goal":"Ще създадеш proxy за плавен монтаж и ще провериш, че финалът връща връзка към camera original.",
  "hook":"Монтажът тече плавно, но export-ът се прави от proxy с по-ниска rezолюция, а оригиналните клипове са offline.",
  "principle":"Proxy е по-леко копие за монтаж; той не заменя camera original и не е архив. Генерирай го по пресет, който съответства на кадрите в timeline, свържи го с източника и обозначи proxy/original пътища. Провери proxy toggle на тестов клип, името, aspect ratio, звук и playback. Финалният export трябва да използва оригиналите според проекта, освен ако brief изрично и аргументирано не казва друго.\n\nСъхранявай proxy отделно от оригинала и пази manifest. Ако проектът се отвори на друга станция, тествай relink към оригинал и направи test export на детайл. Грешен proxy може да има различен кадър или timecode и да доведе до грешни монтажни точки.",
  "detail":"Избери codec/resolution според монтажния компютър, не само размера. Генерирай proxy с уникална папка/суфикс, после потвърди съответствие на duration, frame rate, ориентация и audio channels. Не преименувай оригинали след attach без relink. Преди master: изключи proxies или избери full-res playback, провери representative frame и status на media.",
  "workflow":["Запази и провери оригиналите, структурата и техните имена.","Създай proxy preset и папка, отделена от camera media.","Генерирай sample и сравни frame, timecode, ориентация и звук.","Attach-ни proxy към оригинала и провери включване/изключване в timeline.","Тествай проекта и пътя до оригинала на работната станция, която ще експортира.","Направи кратък full-resolution export, отвори го и провери детайл преди master."],
  "case":"Камерата снима дълги 4K клипове; лаптопът накъсва при scrub. Монтажистът създава proxy, свързва ги по оригиналния media ID и работи локално. Преди export той изключва proxy режима, relink-ва full-res медия и гледа пробен кадър на коса и текст.",
  "failure":"Proxy папката заменя камерата в проекта и последният export не е проверен на пълна резолюция.",
  "fix":"Дръж proxy като отделно свързано производно; изисквай full-resolution test преди одобрен master.",
  "practice":"На тестов проект направи proxy за три клипа, изключи го, премести оригиналите в друга папка и relink-ни проекта. Експортирай кратка проба от оригиналите.",
  "acceptance":"Можеш да превключваш proxy/original, проектът възстановява връзка, а финалната проба показва детайл от оригиналния материал.",
  "source":"Adobe описва създаване и прикачване на proxy media в Premiere: https://helpx.adobe.com/premiere/desktop/organize-media/ingest-proxy-workflow/create-proxies.html",
  "questions":[
   {"type":"quiz","title":"Proxy или original","question":"Каква е ролята на proxy файла?","correct":"Да улесни playback и монтаж, докато запазва връзка към camera original.","wrong":["Да стане единствената архивна копия.","Да замени оригинала във финален master независимо от brief."],"feedback":"Proxy ускорява editing, original остава source of truth."},
   {"type":"scenario","title":"Offline оригинали","question":"Проектът отваря с proxy online, но camera originals offline. Какво правиш преди master?","correct":"Възстановяваш правилния media path и тестваш full-res preview и export.","wrong":["Предаваш proxy export, без да кажеш.","Преименуваш proxies като оригинали."],"feedback":"Потвърди full-resolution източника преди master delivery."},
   {"type":"quiz","title":"Провери proxy attach","question":"Кое сравняваш при sample proxy?","correct":"Изображение, времетраене/timecode, ориентация и звук спрямо оригинала.","wrong":["Само големината на файла.","Само името на папката."],"feedback":"Грешен timecode или кадър може да размести монтажните точки."},
   {"type":"scenario","title":"Нисък детайл при export","question":"Кратката проба показва мека картина и дребен текст. Какво проверяваш?","correct":"Дали проектът рендерира от оригиналите и дали output използва изискваната резолюция.","wrong":["Повишаваш sharpness до максимум.","Одобряваш, защото timeline е плавен."],"feedback":"Playback performance и финалният source resolution са различни критерии."}
  ]},
 {"id":"pv09-09","title":"J-cut и L-cut: звукът подготвя или продължава кадъра","minutes":34,
  "goal":"Ще използваш разделен монтаж на звук и картина, за да свържеш сцени естествено и да запазиш точен смисъл.",
  "hook":"Новият кадър се появява чак след като репликата започне, но срезът разкрива говорещия твърде рано и убива реакцията.",
  "principle":"При J-cut звукът на следващия кадър започва преди картината му; при L-cut звукът от текущата сцена продължава под следващ кадър. И двата хода могат да подготвят място, запазят реакция и прикрият твърд визуален срез. Те не поправят липсваща дума, различен факт или шумен аудио дубъл.\n\nОстави чист handle преди/след репликата, провери lip sync и пази причината кой говори. В интервю кадърът на слушателя може да е полезен, но не трябва да внушава реакция, която не се е случила. Пусни монтажа със затворени очи и без картина, после гледай с картина, за да чуеш/видиш прехода отделно.",
  "detail":"Раздели clip audio/video или използвай linked source със съзнателно разместени ръбове. Направи къс audio fade при ambience; не режи срички. При смяна на говорещ отбележи кой има репликата и кога започва. J/L-cut е монтажен инструмент и може да е неподходящ за точно продуктово демо, където синхронът е доказателство.",
  "workflow":["Маркирай реплика или звук, който може да свърже две сцени.","Провери чисти handles и кой говори в двата кадъра.","Избери J-cut за предварително чуван следващ звук или L-cut за продължаващ звук.","Премести аудио ръба без да отрязваш сричка и добави нужния fade.","Провери sync и реакция с картина, после прослушай без картина.","Върни точния cut, ако преходът променя контекст или подвежда."],
  "case":"Клиентът пита специалист дали услугата е подходяща. L-cut оставя последната част от отговора върху кадър с действие в кабинета. Следващата сцена започва с ambience от мястото преди да се види говорещият, за да се смени пространството естествено.",
  "failure":"Репликата се мести над кадър на човек, който не я е казал, създавайки невярна реакция или endorsement.",
  "fix":"Провери кой изрича думите, какво показва картината и дали преходът променя смисъл.",
  "practice":"Направи две версии на преход между интервю и b-roll: една с J-cut и една с L-cut. Остави различен handle и провери sync, факт и реакция.",
  "acceptance":"Преходът е плавен, сричките и ambience не се късат, а зрителят не се подвежда кой е говорил или какво е станало.",
  "questions":[
   {"type":"quiz","title":"Назови двата cut-а","question":"Кое е J-cut?","correct":"Следващата сцена започва да се чува преди да се покаже.","wrong":["Текущият звук продължава след смяната на картината.","Звукът и картината се съкращават на едно място."],"feedback":"J-cut въвежда аудио от следващата сцена по-рано."},
   {"type":"scenario","title":"Репликата продължава върху b-roll","question":"Звукът от интервюто продължава под кадър на ръце в работа. Какъв е монтажът?","correct":"L-cut, защото звукът от текущата сцена продължава при следваща картина.","wrong":["J-cut, защото всяко преместване на звук е J-cut.","Match cut, защото има нов детайл."],"feedback":"При L-cut картината се сменя, а предишният звук остава."},
   {"type":"quiz","title":"Остави handle","question":"Защо звукът трябва да има чист handle?","correct":"За да започне/завърши без сричка, click или рязко прекъсване.","wrong":["За да удължи произволно клипа.","За да скрие всеки проблем в речта."],"feedback":"Handle позволява естествен преход; той не поправя грешно съдържание."},
   {"type":"scenario","title":"Подвеждаща реакция","question":"Под репликата на клиента си сложил лице на друг човек, който не е чул казаното. Какво правиш?","correct":"Връщаш кадър на действителния говорещ или използваш нейтрален b-roll, който не приписва реакция.","wrong":["Оставяш го, защото монтажът е по-емоционален.","Добавяш субтитър с името на говорещия."],"feedback":"Преходът не трябва да приписва думи или реакция на погрешния човек."}
  ]},
 {"id":"pv09-10","title":"Speed ramp: промени темпото, без да скриеш проблема","minutes":39,
  "goal":"Ще контролираш ускорение и забавяне така, че да подчертаят действие, без видими дупки, артефакти или загубен смисъл.",
  "hook":"Преходът е зрелищен на timeline, но ръката прескача позиции и зрителят не разбира дали процесът е показан в ред.",
  "principle":"Speed ramp е промяна на скоростта във времето, не универсална украса. Използвай го, когато темпото изразява действие, компресира повторение или води поглед към акцент. Slow motion иска достатъчно заснети кадри и чисто движение; повторение на същия кадър не възстановява липсващ детайл. Optical flow може да създаде артефакти около ръце, коса, вода и текст.\n\nПланирай начална и крайна скорост, посока на движение и звук. Избягвай ramp върху инструкция, където зрителят трябва да види точния ход. Провери кадрите в движение, не само на стоп кадър; ако експортираният клип изглежда неестествен, върни простото темпо.",
  "detail":"Постави speed points около действието, направи плавна интерполация и сравни с оригиналната скорост. Провери оптични артефакти и blur, особено при бърз обект. Музиката или звукът може да се отдели или промени; запази естествен звук, ако той обяснява действие. Използвай source frame rate, който позволява желаното забавяне, и провери cadence при target export.",
  "workflow":["Определи коя част трябва да се почувства бърза или бавна и защо.","Провери source frame rate и дали има достатъчно кадри за slow motion.","Постави speed points преди/след ключовото действие.","Избери плавен ramp и провери начална, средна и крайна скорост.","Огледай ръце, контури, вода, текст и sync за артефакти.","Експортирай кратък тест и сравни с версия без ramp."],
  "case":"Реклама показва капка вода върху продукт. Кратко забавяне подчертава удара, после клипът връща нормална скорост за използване. Екипът избира дубъл с достатъчно кадри и маха optical-flow версията, която деформира ръба на капката.",
  "failure":"Slow motion се създава от клип с малко кадри, а интерполацията разтяга ръцете и текста.",
  "fix":"Избери source с подходяща кадрова честота или не забавяй; провери артефакти в export, не само preview.",
  "practice":"Използвай кратък клип с видимо движение. Направи прост срез, умерен ramp и силен ramp; сравни естественост, четимост и артефакти на ръбове.",
  "acceptance":"Промяната на скоростта има причина, действие се разбира, няма видими дупки или warping и аудиото е обмислено.",
  "questions":[
   {"type":"quiz","title":"Избери кадри за slow motion","question":"Какво проверяваш преди забавяне?","correct":"Source frame rate, движение и дали сцената остава четима при target cadence.","wrong":["Само дали ефектът изглежда впечатляващ в preview.","Дали има свободна памет на компютъра."],"feedback":"Източникът трябва да съдържа достатъчно времева информация за планираното забавяне."},
   {"type":"scenario","title":"Артефакт по ръба","question":"Optical flow огъва пръстите в близък кадър. Какво правиш?","correct":"Ползваш по-проста интерполация, друг дубъл или нормална скорост и проверяваш export.","wrong":["Вдигаш размазването, за да скриеш warping.","Оставяш, защото на малък екран може да не личи."],"feedback":"Артефактът е доказателство, че конкретният кадър не понася интерполацията."},
   {"type":"quiz","title":"Не ускорявай инструкцията","question":"Кога speed ramp не е подходящ?","correct":"Когато зрителят трябва да разбере точно поредността или детайлите на сложното действие.","wrong":["Винаги при продуктова реклама.","Само когато няма музика."],"feedback":"Яснотата на действието е по-важна от ефектното темпо."},
   {"type":"scenario","title":"Нямаш кадри за забавяне","question":"Видеото е записано при стандартна честота, но клиентът иска силно slow motion. Какво правиш?","correct":"Показваш теста и предлагаш друг дубъл/кадров режим или умерено темпо, което не прави дупки.","wrong":["Повтаряш всеки кадър и го предаваш като естествен slow motion.","Увеличаваш резолюцията на export."],"feedback":"Не обещавай детайл, който източникът не е записал."}
  ]},
 {"id":"pv09-11","title":"Punch-in и маски: приближи внимание, не пикселите","minutes":40,
  "goal":"Ще изолираш детайл или ще прикриеш монтажен скок, без да губиш резолюция, фокус или естествено движение.",
  "hook":"Punch-in върху говорещия прикрива скок, но изображението омеква и рамката реже брадичката при всяка реплика.",
  "principle":"Punch-in е увеличение на кадъра или промяна на компоновката; маската изолира зона или създава преход. Използвай ги, когато искат вниманието да се премести към предмет, поглед или малък jump cut. Първо провери резолюция и размер на source: цифровото увеличение не създава нов детайл и може да покаже шум.\n\nСледи позицията на очите, headroom и ръбове при движение. Маската се проследява кадър по кадър; feather и ръбът трябва да съвпадат с фона, без ореол. Не замаскирай липсваща реплика или недостоверен кадър. Пусни loop в реален размер, не само увеличен preview.",
  "detail":"При 4K source към 1080 output има известен crop запас, но зависи от реалната резолюция, ориентация, стабилизация и target. Тествай на финалния размер и при движение. За jump cut можеш да смени план, вмъкнеш b-roll или запазиш естествено напрежение; маска не е задължителна.",
  "workflow":["Определи какво трябва да се види по-добре и къде е скокът.","Провери source resolution и target crop.","Настрой scale/position така, че лице, ръце и текст да останат в кадър.","За маска проследи движение, feather, ръб и скриване на фона.","Провери целия участък на финален размер и при движение.","Сравни с по-прост вариант: срез, b-roll или запазен кадър."],
  "case":"Интервю има jump cut между две изречения. Вместо да увеличи кадъра толкова, че да загуби детайл, монтажистът прави леко punch-in и вмъква кратък cutaway на ръцете. Маската се ползва само за графика, не за скриване на грешна реплика.",
  "failure":"Ефектът се увеличава докато скокът изчезне, без да се провери изходната резолюция, фокус и лице.",
  "fix":"Използвай минималния crop, който решава задачата; ако няма запас, избери друга монтажна свръзка.",
  "practice":"Направи две версии на jump cut: лек punch-in и cutaway. Ако добавиш маска, проследи движеща се ръка и провери ръбовете на целия клип.",
  "acceptance":"Лицето/детайлът остава четим, няма видими маскиращи ръбове или ореол, а монтажната промяна не подвежда.",
  "questions":[
   {"type":"quiz","title":"Провери source преди punch-in","question":"Какво ограничава цифровото приближаване?","correct":"Резолюцията, фокусът, шумът, движението и размерът на крайния export.","wrong":["Само дължината на клипа.","Само цветът на фона."],"feedback":"Crop-ът увеличава наличните пиксели; той не създава нов детайл."},
   {"type":"scenario","title":"Маската оставя ореол","question":"При движение има светъл ореол по маската. Какво правиш?","correct":"Проверяваш tracking, feather и контраст на ръба или избираш по-прост кадър/срез.","wrong":["Увеличаваш контраста и оставяш маската.","Разширяваш маската до цял кадър без проверка."],"feedback":"Ореолът показва несъвпадение; коригирай ръба или откажи ефекта."},
   {"type":"quiz","title":"Алтернатива на punch-in","question":"Кой друг монтажен ход може да скрие jump cut?","correct":"Cutaway, промяна на ракурса или чиста пауза, ако запазва смисъла.","wrong":["Увеличаваш картината над възможностите на source.","Слагаш маска върху цялото лице."],"feedback":"По-прост срез може да бъде по-качествен и честен от тежка корекция."},
   {"type":"scenario","title":"Кадърът става мек","question":"На 1080 export лицето е меко след силен crop. Какво правиш?","correct":"Намаляваш приближаването или избираш друг кадър с по-добър source detail.","wrong":["Добавяш sharpening до максимум.","Оставяш, защото timeline preview изглежда рязък."],"feedback":"Оцени финалния файл на целевия размер, не preview."}
  ]},
 {"id":"pv09-12","title":"Motion blur и финална проверка: ефектът трябва да стигне до приемане","minutes":48,
  "goal":"Ще използваш motion blur само когато помага на прехода и ще предадеш възпроизводим проект и проверен master.",
  "hook":"Готовият клип има blur преходи навсякъде, текстът се размазва, а финалният файл има стара версия на субтитрите.",
  "principle":"Motion blur може да свърже бързо движение или прикрие твърд преход, когато посоката и скоростта съвпадат със сцената. Излишният blur замазва продукт, текст и лице; не добавяй го като preset по подразбиране. Провери, че преходът започва/свършва в смислено действие и не заменя липсващ кадър.\n\nФиналният handoff включва одобрен файл, проект, нужни медии/proxies, текстови captions, настройки, права, version note и следваща стъпка. Export се гледа целия; провери първи и последен кадър, черни/празни frames, sync, надписи, цветове, aspect ratio, рендер артефакти и точно име. Предай само одобрения вариант, не работна чернова.",
  "detail":"Направи кратък тест на прехода и прегледай на реалния bitrate/размер. Blur може да предизвика smear, ghosting и размазано четене. При финална инспекция не прескачай на случаен кадър: изгледай непрекъснато целия видео/аудио файл и след това провери техническите метаданни. Съхрани export settings или preset name в readme.",
  "workflow":["Избери преход само ако посоката/действието го оправдават.","Провери малка секция с blur и сравни с обикновен срез.","Рендерирай на целевите export settings и огледай артефакти/текст.","Гледай целия master от първи до последен кадър със звук.","Провери frame, format, sync, captions, име, версия и права.","Пакетирай project и readme; предай одобрения export с конкретен статус."],
  "case":"Клип за услуга има движение на камерата към врата. Един кратък blur преход следва посоката и не закрива текст; останалите сцени ползват чисти cuts. Финалният файл е проверен на телефон, а монтажистът изпраща project, captions и readme с одобрена версия.",
  "failure":"Ефектът се използва на всеки срез; финалната доставка е избрана по име, без цялостно възпроизвеждане.",
  "fix":"Остави ефект само там, където помага, после провери целия export и свързаните файлове.",
  "practice":"Довърши клип от собствените си материали с един justified blur преход. Експортирай, гледай целия файл, поправи един открит проблем и направи handoff пакет за колега.",
  "acceptance":"Одобреният master се отваря, няма видими дефекти, субтитрите/звукът са проверени, а колега намира проекта и настройките.",
  "source":"Adobe обяснява отделен export на burn-in, sidecar и embedded caption tracks; избери по доставката: https://helpx.adobe.com/premiere/desktop/render-and-export/export-files/export-caption-tracks.html",
  "extras":[["Крайният пакет","Предай master, editable project, необходими assets/captions, version note и readme. Не включвай чужди assets, които лицензът не позволява да се предадат."]],
  "questions":[
   {"type":"quiz","title":"Използвай blur с причина","question":"Кога motion blur помага?","correct":"Когато движението и посоката съвпадат със сцената, а детайлът остава четим.","wrong":["На всеки монтажен срез.","Когато липсва ключов кадър."],"feedback":"Ефектът трябва да свърже движение, не да прикрие редакторски пропуск."},
   {"type":"scenario","title":"Текстът се размазва","question":"При тест преходът замазва CTA и лого. Какво правиш?","correct":"Намаляваш или премахваш blur и проверяваш четимостта на export.","wrong":["Увеличаваш blur, за да стане преходът по-плавен.","Оставяш текста, защото се вижда на стоп кадър."],"feedback":"Оцени движение и четимост по време на playback, не само стоп кадър."},
   {"type":"quiz","title":"Финална инспекция","question":"Кое е задължително преди handoff?","correct":"Цялостно възпроизвеждане плюс проверка на версия, звук, captions, формат и файл.","wrong":["Само проверка на последния кадър.","Само статус „render complete“."],"feedback":"Цялото видео може да съдържа кратък дефект, който кадър по избор пропуска."},
   {"type":"scenario","title":"Грешни субтитри във финала","question":"Целият export е добър, но първата версия на субтитрите е вградена. Какво предаваш?","correct":"Нов export от одобрения caption track, после повторна пълна проверка и ново име/версия.","wrong":["Изпращаш текущия, понеже промяната е малка.","Изпращаш два файла с еднакво име и оставяш клиента да избира."],"feedback":"Предай една конкретна одобрена версия и повторно провери файла след поправка."}
  ]}
]
